// CashCollection.jsx
// ============================================================
// Cash Collection — Firestore version
// ------------------------------------------------------------
// Manage session approvals and cash collection across all
// locations.
//
// Firestore collection: PosSessions
// Fields used:
//   SessionID (doc id), ComputerName, UserID,
//   StartDateTime, EndDateTime, StartingAmount,
//   CashSale, CardSale, CreditSale,
//   ExpectedCash, ClosingAmount, Variance,
//   Status ("OPEN" | "CLOSED" | "APPROVED"),
//   ClosedAt, ApprovedBy, ApprovedAt, IsDelete
//
// Operations:
//   - Load all sessions (split client-side by Status)
//   - Close session  → updateDocById
//   - Approve days   → batchWrite (chunked to 500)
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  Clock3,
  Printer,
  CheckCircle,
  ChevronRight,
  ChevronDown,
  Power,
  RefreshCw,
} from "lucide-react";

import { serverTimestamp } from "firebase/firestore";

import {
  COLLECTIONS,
  listCollection,
  updateDocById,
  batchWrite,
} from "../lib/firestore.js";

import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   HELPERS
====================================================== */

function money(value) {
  return Number(value || 0).toLocaleString("en-LK", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

/**
 * Converts any of: Firestore Timestamp | Date | ISO string
 * → valid JS Date (or null).
 */
function toDate(value) {
  if (!value) return null;

  if (typeof value?.toDate === "function") {
    const d = value.toDate();
    return Number.isNaN(d.getTime()) ? null : d;
  }

  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}

/** Local "YYYY-MM-DD" key for day-grouping. */
function localDayKey(date) {
  if (!date) return null;

  const pad = (n) => String(n).padStart(2, "0");

  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate()),
  ].join("-");
}

function duration(minutes) {
  const m = Number(minutes || 0);
  const hours = Math.floor(m / 60);
  const mins = m % 60;

  if (hours === 0) return `${mins}m`;
  return `${hours}h ${mins}m`;
}

function dateText(value) {
  const d = toDate(value);
  if (!d) return "-";

  return d.toLocaleDateString("en-US", {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "2-digit",
  });
}

function shortDate(value) {
  const d = toDate(value);
  return d ? d.toLocaleDateString("en-GB") : "-";
}

function timeText(value) {
  const d = toDate(value);
  return d
    ? d.toLocaleTimeString("en-LK", { hour: "2-digit", minute: "2-digit" })
    : "-";
}

function calculateDuration(startDateTime) {
  const start = toDate(startDateTime);
  if (!start) return 0;

  const minutes = Math.floor((Date.now() - start.getTime()) / 60000);
  return Math.max(minutes, 0);
}

/** Normalize a Firestore session doc into the shape the UI expects. */
function normalizeSession(raw) {
  return {
    ...raw,
    SessionID: raw.id ?? raw.SessionID ?? null,
    Status: String(raw.Status || "").toUpperCase(),
  };
}

/* ======================================================
   COMPONENT
====================================================== */

export default function CashCollection() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [sessions, setSessions] = useState([]);
  const [expandedDays, setExpandedDays] = useState({});
  const [selectedDays, setSelectedDays] = useState([]);
  const [loading, setLoading] = useState(false);
  const [closing, setClosing] = useState(null);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  /* ==================================================
     LOAD DATA
     --------------------------------------------------
     Single collection read → split by Status client-side.
     Session counts are tiny (one per POS per day), so this
     is far cheaper than multiple filtered queries.
  ================================================== */

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      setMessage("");

      const rows = await listCollection(COLLECTIONS.SESSIONS, {
        where: [["IsDelete", "==", 0]],
      });

      setSessions(rows.map(normalizeSession));
    } catch (err) {
      console.error("loadData error:", err);
      setError(err.message || "Unable to load sessions.");
      setSessions([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ==================================================
     CLOSE SESSION
     --------------------------------------------------
     Updates the session doc atomically:
       - ClosingAmount = actual cash entered
       - Variance     = actual − expected
       - EndDateTime  = ISO string (kept for display)
       - ClosedAt     = server timestamp
       - Status       = "CLOSED"
  ================================================== */

  async function closeSession(session) {
    const expected = Number(session.ExpectedCash || 0);

    const value = window.prompt(
      `Enter actual cash.\nExpected cash: Rs.${money(expected)}`
    );

    if (value === null) return;

    const actual = Number(value);

    if (!Number.isFinite(actual) || actual < 0) {
      alert("Please enter a valid amount.");
      return;
    }

    try {
      setClosing(session.SessionID);
      setError("");
      setMessage("");

      const variance = actual - expected;

      await updateDocById(
        COLLECTIONS.SESSIONS,
        session.SessionID,
        {
          ClosingAmount: actual,
          EndDateTime: new Date().toISOString(),
          ClosedAt: serverTimestamp(),
          Variance: variance,
          Status: "CLOSED",
        },
        { username }
      );

      setMessage("Session closed successfully.");
      await loadData();
    } catch (err) {
      console.error("Close session error:", err);
      alert(err.message || "Unable to close session.");
    } finally {
      setClosing(null);
    }
  }

  /* ==================================================
     DERIVED LISTS
  ================================================== */

  const activeSessions = useMemo(
    () => sessions.filter((s) => s.Status === "OPEN"),
    [sessions]
  );

  const closedSessions = useMemo(
    () => sessions.filter((s) => s.Status !== "OPEN"),
    [sessions]
  );

  const closedDays = useMemo(() => {
    const groups = new Map();

    closedSessions.forEach((session) => {
      const date = toDate(
        session.EndDateTime || session.ClosedAt || session.StartDateTime
      );

      if (!date) return;

      const key = localDayKey(date);
      if (!key) return;

      if (!groups.has(key)) {
        groups.set(key, { SessionDate: key, sessions: [] });
      }
      groups.get(key).sessions.push(session);
    });

    return Array.from(groups.values())
      .map((day) => {
        const daySessions = day.sessions;

        return {
          ...day,
          Locations: new Set(
            daySessions.map((s) => s.ComputerName || "Unknown")
          ).size,
          CashTotal: daySessions.reduce(
            (sum, s) => sum + Number(s.CashSale || 0),
            0
          ),
          CardTotal: daySessions.reduce(
            (sum, s) => sum + Number(s.CardSale || 0),
            0
          ),
          CreditTotal: daySessions.reduce(
            (sum, s) => sum + Number(s.CreditSale || 0),
            0
          ),
        };
      })
      .sort((a, b) => (a.SessionDate < b.SessionDate ? 1 : -1));
  }, [closedSessions]);

  /* ==================================================
     UI HANDLERS
  ================================================== */

  function toggleDay(day) {
    const key = String(day.SessionDate);

    setExpandedDays((previous) => ({
      ...previous,
      [key]: !previous[key],
    }));
  }

  function toggleSelectedDay(date) {
    setSelectedDays((previous) =>
      previous.includes(date)
        ? previous.filter((x) => x !== date)
        : [...previous, date]
    );
  }

  /* ==================================================
     APPROVE SELECTED DAYS
     --------------------------------------------------
     Finds every CLOSED session whose local day matches a
     selected day, then batch-updates Status → APPROVED.
     Already-approved sessions are skipped (idempotent).
  ================================================== */

  async function approveSelectedDays() {
    if (selectedDays.length === 0) {
      alert("Please select at least one day.");
      return;
    }

    try {
      setError("");
      setMessage("");
      setLoading(true);

      const toApprove = closedSessions.filter((session) => {
        if (session.Status === "APPROVED") return false;

        const date = toDate(
          session.EndDateTime || session.ClosedAt || session.StartDateTime
        );

        if (!date) return false;

        const key = localDayKey(date);
        return key && selectedDays.includes(key);
      });

      if (toApprove.length === 0) {
        alert("No approvable sessions found in the selected days.");
        return;
      }

      const ops = toApprove.map((s) => ({
        type: "update",
        path: `${COLLECTIONS.SESSIONS}/${s.SessionID}`,
        data: {
          Status: "APPROVED",
          ApprovedBy: username,
          ApprovedAt: serverTimestamp(),
        },
      }));

      // Firestore writeBatch limit is 500 ops
      for (let i = 0; i < ops.length; i += 500) {
        await batchWrite(ops.slice(i, i + 500));
      }

      setMessage(
        `Approved ${toApprove.length} session${
          toApprove.length === 1 ? "" : "s"
        } across ${selectedDays.length} day${
          selectedDays.length === 1 ? "" : "s"
        }.`
      );

      setSelectedDays([]);
      await loadData();
    } catch (err) {
      console.error("Approve days error:", err);
      alert(err.message || "Unable to approve days.");
    } finally {
      setLoading(false);
    }
  }

  /* ==================================================
     RENDER
  ================================================== */

  return (
    <div className="min-h-screen bg-white px-5 py-6 text-slate-900">
      <div className="mx-auto max-w-[1250px]">
        {/* HEADER */}
        <div>
          <h1 className="text-3xl font-bold">Cash Collection</h1>
          <p className="text-slate-500">
            Manage session approvals and cash collection across all locations
          </p>
        </div>

        {/* TABS */}
        <div className="mt-4 inline-flex rounded-lg bg-slate-100 p-1">
          <button
            type="button"
            className="rounded-md bg-white px-5 py-2 text-sm font-medium shadow-sm"
          >
            Sessions
          </button>

          <button
            type="button"
            className="px-5 py-2 text-sm text-slate-500"
            onClick={() => alert("Till Statement is not connected yet.")}
          >
            Till Statement
          </button>
        </div>

        {/* ACTIONS */}
        <div className="mt-5 flex flex-wrap justify-end gap-3">
          <button
            type="button"
            onClick={loadData}
            disabled={loading}
            className="flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm disabled:opacity-50"
          >
            <RefreshCw
              size={17}
              className={loading ? "animate-spin" : ""}
            />
            Refresh
          </button>

          <button
            type="button"
            onClick={() => window.print()}
            className="flex items-center gap-2 rounded-xl border px-4 py-2.5 text-sm"
          >
            <Printer size={17} />
            Print Report
          </button>

          <button
            type="button"
            onClick={approveSelectedDays}
            disabled={selectedDays.length === 0 || loading}
            className="flex items-center gap-2 rounded-xl bg-green-400 px-5 py-2.5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
          >
            <CheckCircle size={18} />
            Approve Selected Days
          </button>
        </div>

        {/* ERROR */}
        {error && (
          <div className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-red-700">
            {error}
          </div>
        )}

        {/* SUCCESS */}
        {message && (
          <div className="mt-5 rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-green-700">
            {message}
          </div>
        )}

        {/* ACTIVE SESSIONS */}
        <section className="mt-6 rounded-2xl border border-orange-200 bg-orange-50/70 p-5">
          <h2 className="mb-5 flex items-center gap-2 text-xl font-semibold text-orange-300">
            <Clock3 size={21} />
            Active Sessions ({activeSessions.length})
          </h2>

          <div className="space-y-4">
            {activeSessions.map((session) => (
              <ActiveSession
                key={session.SessionID}
                session={session}
                closing={closing === session.SessionID}
                onClose={closeSession}
              />
            ))}

            {activeSessions.length === 0 && (
              <div className="rounded-xl border border-orange-200 bg-white p-8 text-center text-slate-500">
                No active sessions
              </div>
            )}
          </div>
        </section>

        {/* CLOSED SESSIONS */}
        <section className="mt-6 rounded-2xl border border-slate-300 bg-white p-5">
          <h2 className="mb-5 text-2xl font-semibold">
            Closed Sessions - Day → Location → Session View
          </h2>

          <div className="space-y-4">
            {closedDays.map((day) => {
              const key = String(day.SessionDate);
              const expanded = expandedDays[key];

              return (
                <div
                  key={key}
                  className="overflow-hidden rounded-xl border border-slate-300"
                >
                  {/* DAY ROW */}
                  <div className="flex flex-col gap-4 px-4 py-4 md:flex-row md:items-center">
                    <div className="flex flex-1 items-center gap-3">
                      <input
                        type="checkbox"
                        checked={selectedDays.includes(key)}
                        onChange={() => toggleSelectedDay(key)}
                        className="h-4 w-4 accent-orange-500"
                      />

                      <button
                        type="button"
                        onClick={() => toggleDay(day)}
                        className="flex items-center gap-2"
                      >
                        {expanded ? (
                          <ChevronDown size={19} />
                        ) : (
                          <ChevronRight size={19} />
                        )}

                        <span className="font-medium">
                          {dateText(`${key}T00:00:00`)}
                        </span>
                      </button>
                    </div>

                    <div className="grid grid-cols-2 gap-6 text-right md:grid-cols-4">
                      <Total label="Locations" value={day.Locations} />
                      <Total label="Cash Total" value={day.CashTotal} green />
                      <Total label="Card Total" value={day.CardTotal} purple />
                      <Total
                        label="Credit Total"
                        value={day.CreditTotal}
                        blue
                      />
                    </div>
                  </div>

                  {/* DAY SESSIONS */}
                  {expanded && (
                    <div className="border-t bg-slate-50 p-4">
                      {day.sessions.map((session) => (
                        <ClosedSession
                          key={session.SessionID}
                          session={session}
                        />
                      ))}

                      {day.sessions.length === 0 && (
                        <p className="py-5 text-center text-slate-500">
                          No sessions found.
                        </p>
                      )}
                    </div>
                  )}
                </div>
              );
            })}

            {closedDays.length === 0 && (
              <div className="p-10 text-center text-slate-500">
                No closed sessions found.
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
}

/* ======================================================
   ACTIVE SESSION CARD
====================================================== */

function ActiveSession({ session, closing, onClose }) {
  const expectedCash =
    session.ExpectedCash !== null && session.ExpectedCash !== undefined
      ? Number(session.ExpectedCash)
      : Number(session.StartingAmount || 0) + Number(session.CashSale || 0);

  const totalSales =
    Number(session.CashSale || 0) +
    Number(session.CardSale || 0) +
    Number(session.CreditSale || 0);

  const durationMinutes = calculateDuration(session.StartDateTime);

  return (
    <div className="rounded-xl border border-orange-200 bg-white/60 p-5">
      <div className="grid gap-6 lg:grid-cols-7 lg:items-center">
        <div>
          <Label>Register</Label>
          <div className="mt-2 font-semibold text-orange-300">
            {session.ComputerName || "Unknown"}
          </div>
          <div className="font-semibold text-orange-200">
            User #{session.UserID ?? "-"}
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Started: {shortDate(session.StartDateTime)}{" "}
            {timeText(session.StartDateTime)}
          </p>
        </div>

        <Metric
          label="Cash Sales"
          value={session.CashSale}
          color="green"
          secondaryLabel="Starting Cash"
          secondaryValue={session.StartingAmount}
          secondaryColor="black"
        />

        <Metric label="Card Sales" value={session.CardSale} color="purple" />

        <Metric
          label="Credit Sales"
          value={session.CreditSale}
          color="blue"
        />

        <Metric
          label="Total Sales"
          value={totalSales}
          color="green"
          secondaryLabel="Expected Cash"
          secondaryValue={expectedCash}
          secondaryColor="black"
        />

        <div>
          <Label>Status</Label>
          <p className="mt-2 font-medium">{session.Status || "OPEN"}</p>
          <Label>Duration</Label>
          <p className="mt-1 text-sm">{duration(durationMinutes)}</p>
        </div>

        <button
          type="button"
          onClick={() => onClose(session)}
          disabled={closing}
          className="flex items-center justify-center gap-2 rounded-xl border border-orange-200 bg-white px-4 py-3 font-medium text-orange-400 hover:bg-orange-50 disabled:opacity-50"
        >
          <Power size={17} />
          {closing ? "Closing..." : "Close Session"}
        </button>
      </div>
    </div>
  );
}

/* ======================================================
   CLOSED SESSION
====================================================== */

function ClosedSession({ session }) {
  const variance =
    session.Variance !== null && session.Variance !== undefined
      ? Number(session.Variance)
      : null;

  const badge =
    session.Status === "APPROVED"
      ? "bg-blue-50 text-blue-700"
      : "bg-green-50 text-green-700";

  return (
    <div className="mb-3 rounded-xl border border-slate-200 bg-white p-5">
      <div className="grid gap-5 md:grid-cols-7 md:items-center">
        <div>
          <p className="text-xs text-slate-500">Computer</p>
          <p className="mt-1 font-semibold">
            {session.ComputerName || "Unknown"}
          </p>
        </div>

        <div>
          <p className="text-xs text-slate-500">User</p>
          <p className="mt-1 font-semibold">#{session.UserID ?? "-"}</p>
        </div>

        <Metric label="Cash" value={session.CashSale} color="green" />
        <Metric label="Card" value={session.CardSale} color="purple" />
        <Metric label="Credit" value={session.CreditSale} color="blue" />

        <Metric
          label="Closing Cash"
          value={session.ClosingAmount}
          color="black"
          secondaryLabel="Expected Cash"
          secondaryValue={session.ExpectedCash}
          secondaryColor="black"
        />

        <div>
          <p className="text-xs text-slate-500">Status</p>

          <span
            className={`mt-2 inline-block rounded-full px-3 py-1 text-xs font-semibold ${badge}`}
          >
            {session.Status || "CLOSED"}
          </span>

          {variance !== null && (
            <p
              className={`mt-2 text-sm font-semibold ${
                variance === 0
                  ? "text-green-600"
                  : variance > 0
                  ? "text-blue-600"
                  : "text-red-600"
              }`}
            >
              Variance: Rs.{money(variance)}
            </p>
          )}
        </div>
      </div>

      <div className="mt-4 flex flex-wrap gap-6 border-t pt-3 text-xs text-slate-500">
        <span>
          Started: {shortDate(session.StartDateTime)}{" "}
          {timeText(session.StartDateTime)}
        </span>

        <span>
          Closed:{" "}
          {session.EndDateTime
            ? `${shortDate(session.EndDateTime)} ${timeText(
                session.EndDateTime
              )}`
            : "-"}
        </span>

        <span>Session ID: {session.SessionID}</span>

        {session.ApprovedBy && (
          <span>
            Approved by {session.ApprovedBy} @{" "}
            {shortDate(session.ApprovedAt)}
          </span>
        )}
      </div>
    </div>
  );
}

/* ======================================================
   METRIC
====================================================== */

function Metric({
  label,
  value,
  color,
  secondaryLabel,
  secondaryValue,
  secondaryColor,
}) {
  const colors = {
    green: "text-green-500",
    purple: "text-purple-500",
    blue: "text-blue-500",
    red: "text-red-500",
    black: "text-slate-900",
  };

  return (
    <div>
      <Label>{label}</Label>

      <p
        className={`mt-2 text-lg font-semibold ${
          colors[color] || colors.black
        }`}
      >
        Rs.{money(value)}
      </p>

      {secondaryLabel && (
        <>
          <Label>{secondaryLabel}</Label>
          <p
            className={`mt-1 text-sm font-medium ${
              colors[secondaryColor || color] || colors.black
            }`}
          >
            Rs.{money(secondaryValue)}
          </p>
        </>
      )}
    </div>
  );
}

/* ======================================================
   LABEL
====================================================== */

function Label({ children }) {
  return <p className="text-sm text-slate-500">{children}</p>;
}

/* ======================================================
   TOTAL
====================================================== */

function Total({ label, value, green, purple, blue }) {
  let color = "text-slate-900";
  if (green) color = "text-green-500";
  if (purple) color = "text-purple-500";
  if (blue) color = "text-blue-500";

  return (
    <div>
      <p className="text-xs text-slate-500">{label}</p>
      <p className={`font-medium ${color}`}>
        {label === "Locations" ? value : `Rs.${money(value)}`}
      </p>
    </div>
  );
}