import React, { useState, useEffect } from 'react';
import { db } from "../firebase.js";// Adjust the import path to your Firebase config
import { collection, doc, getDoc, addDoc, updateDoc, serverTimestamp } from 'firebase/firestore';

const VoucherTemplate = ({ voucherId }) => {
  const [voucher, setVoucher] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isRedeeming, setIsRedeeming] = useState(false);

  // 1. Fetch Voucher Data from Firestore
  useEffect(() => {
    if (!voucherId) {
      setLoading(false);
      return;
    }

    const fetchVoucher = async () => {
      try {
        setLoading(true);
        const voucherRef = doc(db, 'vouchers', voucherId);
        const docSnap = await getDoc(voucherRef);

        if (docSnap.exists()) {
          setVoucher({ id: docSnap.id, ...docSnap.data() });
        } else {
          setError('Voucher not found.');
        }
      } catch (err) {
        console.error('Error fetching voucher:', err);
        setError('Failed to load voucher details.');
      } finally {
        setLoading(false);
      }
    };

    fetchVoucher();
  }, [voucherId]);

  // 2. Handler to Redeem Voucher
  const handleRedeem = async () => {
    if (!voucher || voucher.isRedeemed) return;

    try {
      setIsRedeeming(true);
      const voucherRef = doc(db, 'vouchers', voucher.id);
      
      await updateDoc(voucherRef, {
        isRedeemed: true,
        redeemedAt: serverTimestamp(),
      });

      setVoucher((prev) => ({
        ...prev,
        isRedeemed: true,
      }));
    } catch (err) {
      console.error('Error redeeming voucher:', err);
      setError('Could not redeem voucher.');
    } finally {
      setIsRedeeming(false);
    }
  };

  if (loading) return <div className="p-4 text-center">Loading Voucher...</div>;
  if (error) return <div className="p-4 text-red-500 text-center">{error}</div>;

  return (
    <div className="max-w-md mx-auto bg-white rounded-xl shadow-md overflow-hidden border border-gray-200 m-4 p-6">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-gray-800">
          {voucher?.title || 'Special Discount Voucher'}
        </h2>
        <span className="text-xs font-semibold px-2.5 py-0.5 rounded bg-blue-100 text-blue-800">
          {voucher?.code || 'TOG-2026'}
        </span>
      </div>

      <div className="my-4">
        <p className="text-3xl font-extrabold text-green-600">
          {voucher?.discount ? `${voucher.discount}% OFF` : '10% OFF'}
        </p>
        <p className="text-sm text-gray-500 mt-1">
          {voucher?.description || 'Valid for all upcoming purchases.'}
        </p>
      </div>

      <div className="border-t pt-4 mt-4 flex justify-between items-center">
        <div>
          <p className="text-xs text-gray-400">Status</p>
          <p className={`text-sm font-semibold ${voucher?.isRedeemed ? 'text-red-500' : 'text-green-500'}`}>
            {voucher?.isRedeemed ? 'Redeemed' : 'Active'}
          </p>
        </div>

        <button
          onClick={handleRedeem}
          disabled={voucher?.isRedeemed || isRedeeming}
          className={`px-4 py-2 rounded-lg font-medium text-white transition-colors ${
            voucher?.isRedeemed
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700'
          }`}
        >
          {isRedeeming ? 'Redeeming...' : voucher?.isRedeemed ? 'Used' : 'Redeem Now'}
        </button>
      </div>
    </div>
  );
};

export default VoucherTemplate;