import React, { useEffect, useState } from "react";
import {
  addDoc, collection, deleteDoc, doc, getDoc, getDocs, query, setDoc,
  where, orderBy, limit, serverTimestamp,
} from "firebase/firestore";
import { db } from "../firebase";

// ← PERM
import { usePermissions } from "../hooks/usePermissions.jsx";

const PROMOTIONS = "Promotion";
const PRODUCTS = "ProductMaster";

/* =========================================================
   PROMOTION TYPES  (unchanged)
========================================================= */
const PROMO_TYPES = [
  { value: "BOGO",               label: "Buy 1 Get 1 Free" },
  { value: "BUY_X_GET_Y",        label: "Buy X Get Y Free" },
  { value: "AMOUNT_THRESHOLD",   label: "Amount Threshold → Free Item" },
  { value: "QUANTITY_THRESHOLD", label: "Quantity Threshold → Free Item" },
  { value: "PERCENTAGE",         label: "Percentage Discount" },
  { value: "FIXED",              label: "Fixed Discount" }
];

const emptyForm = {
  promotionCode: "",
  promotionName: "",
  promotionType: "BOGO",
  buyQuantity: 1,
  freeQuantity: 1,
  minimumAmount: 0,
  minimumQuantity: 0,
  discountPercentage: 0,
  discountAmount: 0,
  buyProductCode: "",
  buyProductName: "",
  freeProductCode: "",
  freeProductName: "",
  startDate: "",
  endDate: "",
  isActive: true
};

/* =========================================================
   FIELD VISIBILITY PER TYPE  (unchanged)
========================================================= */
const showBuyProduct  = (t) => ["BOGO", "BUY_X_GET_Y", "PERCENTAGE", "FIXED"].includes(t);
const showFreeProduct = (t) => ["BOGO", "BUY_X_GET_Y", "AMOUNT_THRESHOLD", "QUANTITY_THRESHOLD"].includes(t);
const showBuyQty      = (t) => ["BOGO", "BUY_X_GET_Y"].includes(t);
const showFreeQty     = (t) => ["BOGO", "BUY_X_GET_Y", "AMOUNT_THRESHOLD", "QUANTITY_THRESHOLD"].includes(t);
const showMinAmount   = (t) => t === "AMOUNT_THRESHOLD";
const showMinQty      = (t) => t === "QUANTITY_THRESHOLD";
const showDiscountPct = (t) => t === "PERCENTAGE";
const showDiscountAmt = (t) => t === "FIXED";

/* =========================================================
   COMPONENT
========================================================= */
function Promotion() {

  // =====================================================
  // PERMISSIONS                                        // ← PERM
  // =====================================================
  const { can, loading: permissionsLoading } = usePermissions();  // ← PERM

  const canViewPromotion   = can("Promotion", "View");             // ← PERM
  const canAddPromotion    = can("Promotion", "Add");              // ← PERM
  const canEditPromotion   = can("Promotion", "Edit");             // ← PERM
  const canDeletePromotion = can("Promotion", "Delete");           // ← PERM

  /* --------------------------------------------------
     STATE
  -------------------------------------------------- */
  const [promotions, setPromotions] = useState([]);
  const [form, setForm] = useState(emptyForm);

  const [buyProductSearch, setBuyProductSearch] = useState("");
  const [buyProducts, setBuyProducts] = useState([]);
  const [buyProductLoading, setBuyProductLoading] = useState(false);

  const [freeProductSearch, setFreeProductSearch] = useState("");
  const [freeProducts, setFreeProducts] = useState([]);
  const [freeProductLoading, setFreeProductLoading] = useState(false);

  const [selectedProducts, setSelectedProducts] = useState([]);
  const [productSearch, setProductSearch] = useState("");
  const [products, setProducts] = useState([]);

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const [showForm, setShowForm] = useState(false);
  const [editingID, setEditingID] = useState(null);

  /* --------------------------------------------------
     LOAD PROMOTIONS
  -------------------------------------------------- */
  const loadPromotions = async () => {
    try {
      const snapshot = await getDocs(collection(db, PROMOTIONS));
      const rows = snapshot.docs.map((d) => ({ ...d.data(), PromotionID: d.id }))
        .filter((row) => Number(row.IsDelete ?? 0) !== 1)
        .sort((a, b) => String(a.PromotionCode || "").localeCompare(String(b.PromotionCode || "")));
      setPromotions(rows);
      setError("");
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to load promotions");
    }
  };

  useEffect(() => {
    // ← PERM: skip until permissions resolve / if user can't view
    if (permissionsLoading) return;
    if (!canViewPromotion) return;

    loadPromotions();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canViewPromotion, permissionsLoading]);                     // ← PERM

  /* --------------------------------------------------
     PRODUCT SEARCH HELPERS  (unchanged)
  -------------------------------------------------- */
  const searchByEndpoint = async (value) => {
    const needle = String(value || "").trim().toLowerCase();
    if (!needle) return [];
    const snapshot = await getDocs(collection(db, PRODUCTS));
    return snapshot.docs.map((d) => ({ id: d.id, ...d.data() }))
      .filter((item) => Number(item.IsDelete ?? item.isDelete ?? 0) !== 1)
      .filter((item) => `${item.ProductCode || item.productCode || item.code || ""} ${item.ProductName || item.productName || item.productname || ""}`.toLowerCase().includes(needle))
      .slice(0, 50);
  };

  const searchProducts = async (value) => {
    setProductSearch(value);
    if (!value.trim()) { setProducts([]); return; }
    try {
      setProducts(await searchByEndpoint(value));
    } catch (err) {
      console.error(err);
    }
  };

  const searchBuyProducts = async (value) => {
    setBuyProductSearch(value);
    if (!value.trim()) { setBuyProducts([]); return; }
    try {
      setBuyProductLoading(true);
      setBuyProducts(await searchByEndpoint(value));
    } catch (err) {
      console.error("BUY PRODUCT SEARCH ERROR:", err);
      setBuyProducts([]);
    } finally {
      setBuyProductLoading(false);
    }
  };

  const searchFreeProducts = async (value) => {
    setFreeProductSearch(value);
    if (!value.trim()) { setFreeProducts([]); return; }
    try {
      setFreeProductLoading(true);
      setFreeProducts(await searchByEndpoint(value));
    } catch (err) {
      console.error("FREE PRODUCT SEARCH ERROR:", err);
      setFreeProducts([]);
    } finally {
      setFreeProductLoading(false);
    }
  };

  const selectBuyProduct = (product) => {
    setForm(prev => ({
      ...prev,
      buyProductCode: product.ProductCode || "",
      buyProductName: product.ProductName || ""
    }));
    setBuyProductSearch("");
    setBuyProducts([]);
  };

  const selectFreeProduct = (product) => {
    setForm(prev => ({
      ...prev,
      freeProductCode: product.ProductCode || "",
      freeProductName: product.ProductName || ""
    }));
    setFreeProductSearch("");
    setFreeProducts([]);
  };

  const clearBuyProduct = () => {
    setForm(prev => ({ ...prev, buyProductCode: "", buyProductName: "" }));
    setBuyProductSearch("");
    setBuyProducts([]);
  };

  const clearFreeProduct = () => {
    setForm(prev => ({ ...prev, freeProductCode: "", freeProductName: "" }));
    setFreeProductSearch("");
    setFreeProducts([]);
  };

  /* --------------------------------------------------
     LEGACY MULTI-PRODUCT PICKER  (unchanged)
  -------------------------------------------------- */
  const addProduct = (product) => {
    if (selectedProducts.some(p => p.ProductCode === product.ProductCode)) return;
    setSelectedProducts(prev => [...prev, product]);
    setProductSearch("");
    setProducts([]);
  };

  const removeProduct = (code) => {
    setSelectedProducts(prev => prev.filter(p => p.ProductCode !== code));
  };

  /* --------------------------------------------------
     FORM CHANGE  (unchanged)
  -------------------------------------------------- */
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value
    }));
  };

  const handleTypeChange = (e) => {
    const newType = e.target.value;

    setForm(prev => ({
      ...prev,
      promotionType: newType,
      buyQuantity:        newType === "BOGO" ? 1 : (prev.buyQuantity || 1),
      freeQuantity:       newType === "BOGO" ? 1 : (prev.freeQuantity || 1),
      minimumAmount:      showMinAmount(newType)   ? prev.minimumAmount : 0,
      minimumQuantity:    showMinQty(newType)      ? prev.minimumQuantity : 0,
      discountPercentage: showDiscountPct(newType) ? prev.discountPercentage : 0,
      discountAmount:     showDiscountAmt(newType) ? prev.discountAmount : 0,
      buyProductCode:     showBuyProduct(newType)  ? prev.buyProductCode : "",
      buyProductName:     showBuyProduct(newType)  ? prev.buyProductName : "",
      freeProductCode:    showFreeProduct(newType) ? prev.freeProductCode : "",
      freeProductName:    showFreeProduct(newType) ? prev.freeProductName : ""
    }));

    setBuyProductSearch("");
    setBuyProducts([]);
    setFreeProductSearch("");
    setFreeProducts([]);
  };

  /* --------------------------------------------------
     NEW / EDIT
  -------------------------------------------------- */
  const newPromotion = () => {
    // ← PERM
    if (!canAddPromotion) {
      setError("You do not have permission to create promotions.");
      return;
    }

    setForm(emptyForm);
    setSelectedProducts([]);
    setBuyProductSearch("");
    setBuyProducts([]);
    setFreeProductSearch("");
    setFreeProducts([]);
    setProductSearch("");
    setProducts([]);
    setEditingID(null);
    setMessage("");
    setError("");
    setShowForm(true);
  };

  const editPromotion = async (promotion) => {
    if (!canEditPromotion) {
      setError("You do not have permission to edit promotions.");
      return;
    }
    try {
      const snap = await getDoc(doc(db, PROMOTIONS, String(promotion.PromotionID)));
      if (!snap.exists()) throw new Error("Promotion not found.");
      const d = snap.data();
      setForm({
        promotionCode: d.PromotionCode || d.promotionCode || "",
        promotionName: d.PromotionName || d.promotionName || "",
        promotionType: d.PromotionType || d.promotionType || "BOGO",
        buyQuantity: Number(d.BuyQuantity ?? d.buyQuantity ?? 1),
        freeQuantity: Number(d.FreeQuantity ?? d.freeQuantity ?? 1),
        minimumAmount: Number(d.MinimumAmount ?? d.minimumAmount ?? 0),
        minimumQuantity: Number(d.MinimumQuantity ?? d.minimumQuantity ?? 0),
        discountPercentage: Number(d.DiscountPercentage ?? d.discountPercentage ?? 0),
        discountAmount: Number(d.DiscountAmount ?? d.discountAmount ?? 0),
        buyProductCode: d.BuyProductCode || d.buyProductCode || "",
        buyProductName: d.BuyProductName || d.buyProductName || "",
        freeProductCode: d.FreeProductCode || d.freeProductCode || "",
        freeProductName: d.FreeProductName || d.freeProductName || "",
        startDate: String(d.StartDate || d.startDate || "").substring(0, 10),
        endDate: String(d.EndDate || d.endDate || "").substring(0, 10),
        isActive: Boolean(d.IsActive ?? d.isActive ?? true),
      });
      setSelectedProducts(Array.isArray(d.Products) ? d.Products : Array.isArray(d.products) ? d.products.map((x) => ({ InvProductMasterID: x.productID, ProductCode: x.productCode, ProductName: x.productName })) : []);
      setEditingID(promotion.PromotionID);
      setShowForm(true); setError(""); setMessage("");
    } catch (err) { console.error(err); setError(err.message || "Unable to load promotion"); }
  };

  /* --------------------------------------------------
     VALIDATION  (unchanged)
  -------------------------------------------------- */
  const validateForm = () => {
    if (!form.promotionCode.trim()) return "Promotion code is required";
    if (!form.promotionName.trim()) return "Promotion name is required";
    if (!form.startDate || !form.endDate) return "Start date and end date are required";
    if (new Date(form.endDate) < new Date(form.startDate))
      return "End date must be after start date";

    const t = form.promotionType;

    if (showFreeProduct(t) && !form.freeProductCode.trim()) {
      return "Free product is required for this promotion type";
    }

    if (t === "BOGO" || t === "BUY_X_GET_Y") {
      if (Number(form.buyQuantity) <= 0) return "Buy quantity must be greater than 0";
      if (Number(form.freeQuantity) <= 0) return "Free quantity must be greater than 0";
    }

    if (t === "AMOUNT_THRESHOLD" && Number(form.minimumAmount) <= 0) {
      return "Minimum purchase amount must be greater than 0";
    }
    if (t === "QUANTITY_THRESHOLD" && Number(form.minimumQuantity) <= 0) {
      return "Minimum quantity must be greater than 0";
    }
    if (t === "PERCENTAGE" && Number(form.discountPercentage) <= 0) {
      return "Discount percentage must be greater than 0";
    }
    if (t === "FIXED" && Number(form.discountAmount) <= 0) {
      return "Discount amount must be greater than 0";
    }

    return null;
  };

  /* --------------------------------------------------
     SAVE
  -------------------------------------------------- */
  const savePromotion = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    // ----- Permission guards -----                        // ← PERM
    if (editingID && !canEditPromotion) {
      setError("You do not have permission to edit promotions.");
      return;
    }
    if (!editingID && !canAddPromotion) {
      setError("You do not have permission to create promotions.");
      return;
    }

    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);

    try {
      const payload = {
        PromotionCode: form.promotionCode.trim(),
        PromotionName: form.promotionName.trim(),
        PromotionType: form.promotionType,
        BuyQuantity: Number(form.buyQuantity || 0),
        FreeQuantity: Number(form.freeQuantity || 0),
        MinimumAmount: Number(form.minimumAmount || 0),
        MinimumQuantity: Number(form.minimumQuantity || 0),
        DiscountPercentage: Number(form.discountPercentage || 0),
        DiscountAmount: Number(form.discountAmount || 0),
        BuyProductCode: form.buyProductCode.trim() || null,
        BuyProductName: form.buyProductName.trim() || null,
        FreeProductCode: form.freeProductCode.trim() || null,
        FreeProductName: form.freeProductName.trim() || null,
        StartDate: form.startDate,
        EndDate: form.endDate,
        IsActive: form.isActive ? 1 : 0,
        Products: selectedProducts.map((item) => ({
          productID: item.InvProductMasterID || item.id || "",
          productCode: item.ProductCode || item.productCode || "",
          productName: item.ProductName || item.productName || "",
        })),
        IsDelete: 0,
        ModifiedAt: serverTimestamp(),
      };
      if (editingID) {
        await setDoc(doc(db, PROMOTIONS, String(editingID)), payload, { merge: true });
      } else {
        payload.CreatedAt = serverTimestamp();
        await addDoc(collection(db, PROMOTIONS), payload);
      }

      setMessage(editingID ? "Promotion updated successfully" : "Promotion created successfully");
        setShowForm(false);
        setForm(emptyForm);
        setSelectedProducts([]);
        setEditingID(null);
        await loadPromotions();
    } catch (err) {
      console.error(err);
      setError(err.message || "Unable to save promotion");
    } finally {
      setLoading(false);
    }
  };

  /* --------------------------------------------------
     DELETE
  -------------------------------------------------- */
  const deletePromotion = async (id) => {
    if (!canDeletePromotion) { setError("You do not have permission to delete promotions."); return; }
    if (!window.confirm("Delete this promotion?")) return;
    try {
      await deleteDoc(doc(db, PROMOTIONS, String(id)));
      setMessage("Promotion deleted successfully");
      await loadPromotions();
    } catch (err) { console.error(err); setError(err.message || "Unable to delete promotion"); }
  };

  /* --------------------------------------------------
     DESCRIPTION  (unchanged)
  -------------------------------------------------- */
  const getDescription = (p) => {
    const type = String(p.PromotionType || "").toUpperCase();

    switch (type) {
      case "BOGO":
      case "BUY_1_GET_1":
      case "BUY_1_GET_1_FREE":
        return `Buy ${p.BuyQuantity} Get ${p.FreeQuantity} Free`;

      case "BUY_X_GET_Y":
      case "BUY_X_GET_Y_FREE":
      case "BXGY":
        return `Buy ${p.BuyQuantity} Get ${p.FreeQuantity} Free`;

      case "AMOUNT_THRESHOLD":
      case "AMOUNT_FREE":
        return `Spend ≥ ${Number(p.MinimumAmount || 0).toLocaleString()} → ${p.FreeQuantity} Free`;

      case "QUANTITY_THRESHOLD":
      case "QTY_FREE":
        return `Buy ≥ ${p.MinimumQuantity} Qty → ${p.FreeQuantity} Free`;

      case "PERCENTAGE":
      case "PERCENT":
        return `${p.DiscountPercentage}% Discount`;

      case "FIXED":
      case "FIXED_AMOUNT":
        return `LKR ${Number(p.DiscountAmount || 0).toLocaleString()} Discount`;

      default:
        return "";
    }
  };

  // =====================================================
  // COMPUTED                                            // ← PERM
  // =====================================================
  const isEditing = Boolean(editingID);
  const saveAllowed =
    (isEditing && canEditPromotion) || (!isEditing && canAddPromotion);
  const readOnlyEdit = isEditing && !canEditPromotion;

  // =====================================================
  // ACCESS GATE                                         // ← PERM
  // =====================================================
  if (permissionsLoading) {                                // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewPromotion) {                                 // ← PERM
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Promotion Management.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Promotion</code>
          </p>
        </div>
      </div>
    );
  }

  /* =========================================================
     RENDER
  ========================================================= */
  return (
    <div className="min-h-screen bg-gray-100 p-6">

      {/* HEADER */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-800">
            Promotion Management
          </h1>
          <p className="text-gray-500 mt-1">
            Create and manage POS promotions
          </p>
        </div>

        <div className="flex items-center gap-3">
          {/* ← PERM: read-only badge */}
          {readOnlyEdit && (                              /* ← PERM */
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}

          {/* ← PERM: New button only when user can Add */}
          {canAddPromotion && (                           /* ← PERM */
            <button
              onClick={newPromotion}
              className="bg-orange-500 hover:bg-orange-600 text-white px-5 py-3 rounded-lg font-semibold"
            >
              + New Promotion
            </button>
          )}
        </div>
      </div>

      {/* MESSAGES */}
      {message && (
        <div className="bg-green-100 text-green-700 p-4 rounded-lg mb-4">
          {message}
        </div>
      )}
      {error && (
        <div className="bg-red-100 text-red-700 p-4 rounded-lg mb-4">
          {error}
        </div>
      )}

      {/* LIST */}
      <div className="bg-white rounded-xl shadow">
        <div className="p-5 border-b">
          <h2 className="text-xl font-bold">Promotions</h2>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                <th className="text-left p-4">Code</th>
                <th className="text-left p-4">Promotion</th>
                <th className="text-left p-4">Type</th>
                <th className="text-left p-4">Rule</th>
                <th className="text-left p-4">Start</th>
                <th className="text-left p-4">End</th>
                <th className="text-left p-4">Status</th>
                <th className="text-left p-4">Actions</th>
              </tr>
            </thead>

            <tbody>
              {promotions.map(p => (
                <tr key={p.PromotionID} className="border-t">
                  <td className="p-4 font-semibold">{p.PromotionCode}</td>
                  <td className="p-4">{p.PromotionName}</td>
                  <td className="p-4">{p.PromotionType}</td>
                  <td className="p-4">{getDescription(p)}</td>
                  <td className="p-4">{p.StartDate?.substring(0, 10)}</td>
                  <td className="p-4">{p.EndDate?.substring(0, 10)}</td>
                  <td className="p-4">
                    {p.IsActive ? (
                      <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-sm">
                        Active
                      </span>
                    ) : (
                      <span className="bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-sm">
                        Inactive
                      </span>
                    )}
                  </td>
                  <td className="p-4">
                    {/* ← PERM: gate action buttons */}
                    <div className="flex gap-2">
                      {canEditPromotion && (              /* ← PERM */
                        <button
                          onClick={() => editPromotion(p)}
                          className="border px-3 py-2 rounded hover:bg-gray-100"
                          title="Edit"
                        >
                          ✏️
                        </button>
                      )}

                      {canDeletePromotion && (            /* ← PERM */
                        <button
                          onClick={() => deletePromotion(p.PromotionID)}
                          className="border px-3 py-2 rounded text-red-600 hover:bg-red-50"
                          title="Delete"
                        >
                          🗑
                        </button>
                      )}

                      {!canEditPromotion && !canDeletePromotion && (
                        <span className="text-xs text-slate-400">
                          No actions
                        </span>
                      )}
                    </div>
                  </td>
                </tr>
              ))}

              {promotions.length === 0 && (
                <tr>
                  <td colSpan="8" className="text-center p-10 text-gray-500">
                    No promotions found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* FORM MODAL */}
      {showForm && saveAllowed && (                        /* ← PERM */
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[95vh] overflow-y-auto">

            <div className="flex justify-between items-center p-6 border-b sticky top-0 bg-white z-10">
              <div>
                <h2 className="text-2xl font-bold">
                  {editingID ? "Edit Promotion" : "Create Promotion"}
                </h2>
                <p className="text-gray-500">Configure promotion rules</p>
              </div>
              <button
                onClick={() => setShowForm(false)}
                className="text-2xl text-gray-500 hover:text-gray-800"
              >
                ×
              </button>
            </div>

            <form onSubmit={savePromotion} className="p-6">

              {/* BASIC INFO */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block font-medium mb-2">Promotion Code</label>
                  <input
                    name="promotionCode"
                    value={form.promotionCode}
                    onChange={handleChange}
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="PROMO001"
                    required
                  />
                </div>

                <div>
                  <label className="block font-medium mb-2">Promotion Name</label>
                  <input
                    name="promotionName"
                    value={form.promotionName}
                    onChange={handleChange}
                    className="w-full border rounded-lg px-4 py-3"
                    placeholder="Buy 1 Get 1 Free"
                    required
                  />
                </div>

                <div>
                  <label className="block font-medium mb-2">Promotion Type</label>
                  <select
                    name="promotionType"
                    value={form.promotionType}
                    onChange={handleTypeChange}
                    className="w-full border rounded-lg px-4 py-3"
                  >
                    {PROMO_TYPES.map(t => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center gap-3 pt-8">
                  <input
                    type="checkbox"
                    name="isActive"
                    checked={form.isActive}
                    onChange={handleChange}
                    className="w-5 h-5"
                  />
                  <label className="font-medium">Active</label>
                </div>
              </div>

              {/* RULE */}
              <div className="mt-8 border rounded-xl p-5">
                <h3 className="text-lg font-bold mb-5">Promotion Rule</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

                  {showBuyQty(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Buy Quantity</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="buyQuantity"
                        value={form.buyQuantity}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                      />
                    </div>
                  )}

                  {showFreeQty(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Free Quantity</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="freeQuantity"
                        value={form.freeQuantity}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                      />
                    </div>
                  )}

                  {showMinAmount(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Minimum Purchase Amount</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="minimumAmount"
                        value={form.minimumAmount}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                        placeholder="10000"
                      />
                    </div>
                  )}

                  {showMinQty(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Minimum Quantity</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="minimumQuantity"
                        value={form.minimumQuantity}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                        placeholder="10"
                      />
                    </div>
                  )}

                  {showDiscountPct(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Discount Percentage</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="discountPercentage"
                        value={form.discountPercentage}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                        placeholder="10"
                      />
                    </div>
                  )}

                  {showDiscountAmt(form.promotionType) && (
                    <div>
                      <label className="block font-medium mb-2">Discount Amount</label>
                      <input
                        type="number" step="0.01" min="0"
                        name="discountAmount"
                        value={form.discountAmount}
                        onChange={handleChange}
                        className="w-full border rounded-lg px-4 py-3"
                        placeholder="500"
                      />
                    </div>
                  )}
                </div>

                <p className="text-xs text-gray-500 mt-4">
                  Leave thresholds at 0 unless you want to gate the promotion
                  behind a minimum spend or quantity.
                </p>
              </div>

              {/* BUY PRODUCT */}
              {showBuyProduct(form.promotionType) && (
                <div className="mt-6 border rounded-xl p-5">
                  <h3 className="text-lg font-bold mb-2">Buy Product</h3>
                  <p className="text-gray-500 mb-4">
                    {form.promotionType === "BOGO"
                      ? "Product the customer must purchase. Leave blank to use the free product (classic same-product BOGO)."
                      : form.promotionType === "BUY_X_GET_Y"
                        ? "Product the customer must purchase to trigger the promotion."
                        : "Optional. Restrict the discount to purchases of this product."}
                  </p>

                  <div className="relative">
                    <input
                      type="text"
                      value={buyProductSearch}
                      onChange={(e) => searchBuyProducts(e.target.value)}
                      className="w-full border rounded-lg px-4 py-3"
                      placeholder="Search by product code or name..."
                      autoComplete="off"
                    />

                    {buyProductLoading && (
                      <div className="absolute right-4 top-4 text-sm text-gray-500">
                        Searching...
                      </div>
                    )}

                    {buyProducts.length > 0 && (
                      <div className="absolute z-50 left-0 right-0 mt-1 bg-white border rounded-lg shadow-xl max-h-60 overflow-y-auto">
                        {buyProducts.map(product => (
                          <button
                            type="button"
                            key={product.InvProductMasterID}
                            onClick={() => selectBuyProduct(product)}
                            className="w-full text-left px-4 py-3 hover:bg-orange-50 border-b last:border-b-0"
                          >
                            <div className="font-semibold text-gray-800">
                              {product.ProductCode}
                            </div>
                            <div className="text-sm text-gray-600">
                              {product.ProductName}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}

                    {buyProductSearch.trim() && !buyProductLoading && buyProducts.length === 0 && (
                      <div className="absolute z-50 left-0 right-0 mt-1 bg-white border rounded-lg shadow p-4 text-gray-500">
                        No products found
                      </div>
                    )}
                  </div>

                  {form.buyProductCode && (
                    <div className="mt-4 bg-blue-50 border border-blue-200 rounded-lg p-4 flex justify-between items-center">
                      <div>
                        <div className="text-sm text-blue-600 font-medium">
                          Selected Buy Product
                        </div>
                        <div className="font-bold text-gray-800">
                          {form.buyProductCode}
                        </div>
                        <div className="text-gray-600">
                          {form.buyProductName}
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={clearBuyProduct}
                        className="text-red-600 hover:text-red-800 font-medium"
                      >
                        Remove
                      </button>
                    </div>
                  )}
                </div>
              )}

              {/* FREE PRODUCT */}
              {showFreeProduct(form.promotionType) && (
                <div className="mt-6 border rounded-xl p-5">
                  <h3 className="text-lg font-bold mb-2">Free Product</h3>
                  <p className="text-gray-500 mb-4">
                    Product that will be given free when the promotion triggers.
                  </p>

                  <div className="relative">
                    <input
                      type="text"
                      value={freeProductSearch}
                      onChange={(e) => searchFreeProducts(e.target.value)}
                      className="w-full border rounded-lg px-4 py-3"
                      placeholder="Search by product code or name..."
                      autoComplete="off"
                    />

                    {freeProductLoading && (
                      <div className="absolute right-4 top-4 text-sm text-gray-500">
                        Searching...
                      </div>
                    )}

                    {freeProducts.length > 0 && (
                      <div className="absolute z-50 left-0 right-0 mt-1 bg-white border rounded-lg shadow-xl max-h-60 overflow-y-auto">
                        {freeProducts.map(product => (
                          <button
                            type="button"
                            key={product.InvProductMasterID}
                            onClick={() => selectFreeProduct(product)}
                            className="w-full text-left px-4 py-3 hover:bg-orange-50 border-b last:border-b-0"
                          >
                            <div className="font-semibold text-gray-800">
                              {product.ProductCode}
                            </div>
                            <div className="text-sm text-gray-600">
                              {product.ProductName}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}

                    {freeProductSearch.trim() && !freeProductLoading && freeProducts.length === 0 && (
                      <div className="absolute z-50 left-0 right-0 mt-1 bg-white border rounded-lg shadow p-4 text-gray-500">
                        No products found
                      </div>
                    )}
                  </div>

                  {form.freeProductCode && (
                    <div className="mt-4 bg-green-50 border border-green-200 rounded-lg p-4 flex justify-between items-center">
                      <div>
                        <div className="text-sm text-green-600 font-medium">
                          Selected Free Product
                        </div>
                        <div className="font-bold text-gray-800">
                          {form.freeProductCode}
                        </div>
                        <div className="text-gray-600">
                          {form.freeProductName}
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={clearFreeProduct}
                        className="text-red-600 hover:text-red-800 font-medium"
                      >
                        Remove
                      </button>
                    </div>
                  )}
                </div>
              )}

              {/* LEGACY MULTI-PRODUCT PICKER */}
              <div className="mt-6 border rounded-xl p-5">
                <h3 className="text-lg font-bold">Promotion Products (optional)</h3>
                <p className="text-gray-500 mb-4">
                  Additional products tracked with this promotion. The POS
                  engine uses the Buy / Free product fields above.
                </p>

                <input
                  value={productSearch}
                  onChange={e => searchProducts(e.target.value)}
                  className="w-full border rounded-lg px-4 py-3"
                  placeholder="Search product..."
                />

                {products.length > 0 && (
                  <div className="border rounded-lg mt-2 max-h-48 overflow-y-auto">
                    {products.map(product => (
                      <button
                        type="button"
                        key={product.InvProductMasterID}
                        onClick={() => addProduct(product)}
                        className="w-full text-left px-4 py-3 hover:bg-gray-100 border-b"
                      >
                        <strong>{product.ProductCode}</strong> - {product.ProductName}
                      </button>
                    ))}
                  </div>
                )}

                {selectedProducts.length > 0 && (
                  <div className="mt-4 space-y-2">
                    {selectedProducts.map(product => (
                      <div
                        key={product.ProductCode}
                        className="flex justify-between items-center bg-gray-50 p-3 rounded-lg"
                      >
                        <div>
                          <strong>{product.ProductCode}</strong> - {product.ProductName}
                        </div>
                        <button
                          type="button"
                          onClick={() => removeProduct(product.ProductCode)}
                          className="text-red-600"
                        >
                          Remove
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* DATES */}
              <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-5">
                <div>
                  <label className="block font-medium mb-2">Start Date</label>
                  <input
                    type="date"
                    name="startDate"
                    value={form.startDate}
                    onChange={handleChange}
                    className="w-full border rounded-lg px-4 py-3"
                    required
                  />
                </div>
                <div>
                  <label className="block font-medium mb-2">End Date</label>
                  <input
                    type="date"
                    name="endDate"
                    value={form.endDate}
                    onChange={handleChange}
                    className="w-full border rounded-lg px-4 py-3"
                    required
                  />
                </div>
              </div>

              {/* BUTTONS */}
              <div className="flex justify-end gap-3 mt-8">
                <button
                  type="button"
                  onClick={() => setShowForm(false)}
                  className="border px-6 py-3 rounded-lg"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={loading}
                  className="bg-orange-500 hover:bg-orange-600 disabled:bg-gray-400 text-white px-7 py-3 rounded-lg font-semibold"
                >
                  {loading
                    ? "Saving..."
                    : editingID
                      ? "Update Promotion"
                      : "Save Promotion"}
                </button>
              </div>

            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Promotion;