// Salesregister.jsx — Firestore version
// ============================================================
// Firestore collections used:
//   - Sales        (one doc per invoice; embeds itemsList[])
//   - Products     (for cost + supplier/department lookup)
//   - Locations    (via COLLECTIONS.LOCATIONS)
//
// All six aggregations (summary / bill-wise / product-wise /
// supplier-wise / department-wise / daily-trend) plus the
// billwise/lines endpoint are computed from a single in-memory
// flat array of sale lines. No per-endpoint fetches.
//
// Line cost resolution:
//   line.Cost ?? line.CostPrice ?? Products[ProductCode].CostPrice ?? 0
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  Download,
  Calendar,
  DollarSign,
  TrendingUp,
  Package,
  FileText,
  RefreshCw,
  Loader2,
  ChevronRight,
  ChevronDown,
  BarChart3,
} from "lucide-react";

import { COLLECTIONS, listCollection } from "../lib/firestore.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* =========================================================
   COLLECTIONS
========================================================= */

const SALES = COLLECTIONS?.SALES ?? "Sales";
const PRODUCTS = COLLECTIONS?.PRODUCTS ?? "Products";

/* =========================================================
   HELPERS
========================================================= */

const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

const getLocationID = (user) =>
  Number(
    user?.LocationID ??
      user?.locationID ??
      user?.locationid ??
      user?.location ??
      0
  );

const formatMoney = (value) =>
  toNumber(value).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

const formatNumber = (value, decimals = 2) =>
  toNumber(value).toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });

const formatInt = (value) =>
  toNumber(value).toLocaleString("en-US");

const toDateInput = (d) => {
  const dt = d instanceof Date ? d : new Date(d);
  const yyyy = dt.getFullYear();
  const mm = String(dt.getMonth() + 1).padStart(2, "0");
  const dd = String(dt.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
};

const todayStr = () => toDateInput(new Date());

// Compare YYYY-MM-DD prefixes (works for Firestore Timestamp,
// ISO strings, and JS Date serialized by Firestore)
const dayString = (value) => {
  if (!value) return "";
  if (typeof value === "string") return value.slice(0, 10);
  if (value instanceof Date) return toDateInput(value);
  // Firestore Timestamp
  if (typeof value.toDate === "function") {
    return toDateInput(value.toDate());
  }
  // Timestamp-like { seconds, nanoseconds }
  if (typeof value.seconds === "number") {
    return toDateInput(new Date(value.seconds * 1000));
  }
  return String(value).slice(0, 10);
};

/* =========================================================
   FILTER OPTIONS
========================================================= */

const CUSTOMER_TYPES = [
  { value: "", label: "All Types" },
  { value: "1", label: "Walk-in" },
  { value: "2", label: "Regular" },
  { value: "3", label: "Wholesale" },
  { value: "4", label: "VIP" },
];

const PAYMENT_METHODS = [
  { value: "", label: "All Methods" },
  { value: "CASH", label: "Cash" },
  { value: "CREDIT", label: "Credit" },
  { value: "CARD", label: "Card" },
  { value: "VOUCHER", label: "Voucher" },
  { value: "CHECK", label: "Check" },
  { value: "TRANSFER", label: "Transfer" },
  { value: "SPLIT", label: "Split" },
];

const TABS = [
  { key: "billwise", label: "Bill-wise" },
  { key: "productwise", label: "Products" },
  { key: "supplierwise", label: "Suppliers" },
  { key: "departmentwise", label: "Departments" },
];

/* =========================================================
   FLATTEN + AGGREGATE
========================================================= */

// Flatten all Sales docs into a single array of sale-line objects.
function flattenSales(sales, productMap) {
  const lines = [];

  sales.forEach((sale) => {
    const saleDate = pick(sale, "RecDate", "SaleDate", "InvoiceDate");
    const receipt = pick(sale, "Receipt", "receipt", "InvoiceNumber");
    const customerName =
      pick(sale, "CustomerName", "Customer", "customer") || "";
    const cashier = pick(sale, "Cashier", "cashier", "Username") || "";
    const locationID = pick(sale, "LocationID", "locationID");
    const saleCustomerType = String(
      pick(sale, "CustomerType", "CustomerTypeID", "CustomerTypeId") || ""
    );
    const salePaymentMethod = String(
      pick(sale, "PaymentMethod", "PayTypeID", "payTypeID") || ""
    ).toUpperCase();

    const items = Array.isArray(sale.itemsList)
      ? sale.itemsList
      : Array.isArray(sale.items)
        ? sale.items
        : [];

    items.forEach((line) => {
      const productCode = pick(
        line,
        "ProductCode",
        "productcode",
        "ItemCode"
      );
      const product = productMap[productCode] || {};

      const qty = toNumber(pick(line, "Qty", "Quantity"));
      const unitPrice = toNumber(pick(line, "Price", "UnitPrice"));
      const gross = qty * unitPrice;
      const discountPct = toNumber(
        pick(line, "FixedDiscountPercentage", "DiscountPercentage")
      );
      const lineDiscount = toNumber(
        pick(line, "FixedDiscount", "DiscountAmount")
      ) || (gross * discountPct) / 100;
      const net = toNumber(pick(line, "Nett", "NetAmount")) || (gross - lineDiscount);

      // If stored: use line.CostAmount / line.Profit directly
      const cost = toNumber(
        pick(line, "Cost", "CostPrice", "UnitCost")
      ) || toNumber(pick(product, "CostPrice", "costprice"));
      const costAmount = qty * cost;
      const profit = net - costAmount;

      lines.push({
        Receipt: String(receipt),
        SaleDate: saleDate,
        SaleDay: dayString(saleDate),
        CustomerName: String(customerName),
        Cashier: String(cashier),
        LocationID: String(locationID ?? ""),
        CustomerType: saleCustomerType,
        PaymentMethod: salePaymentMethod,

        ProductCode: String(productCode || ""),
        ProductName:
          pick(product, "ProductName", "productname") ||
          pick(line, "Descrip", "ProductName", "ItemName") ||
          "",
        SupplierName:
          pick(product, "SupplierName", "suppliername") ||
          pick(line, "SupplierName") ||
          "(No Supplier)",
        DepartmentName:
          pick(product, "DepartmentName", "departmentname") ||
          pick(line, "DepartmentName") ||
          "(No Department)",

        Qty: qty,
        GrossAmount: gross,
        LineDiscount: lineDiscount,
        NetAmount: net,
        CostAmount: costAmount,
        Profit: profit,
      });
    });
  });

  return lines;
}

// Sum a numeric field across an array of line/row objects
const sumBy = (rows, field) =>
  rows.reduce((acc, r) => acc + toNumber(r[field]), 0);

// Group rows by a key builder
const groupBy = (rows, keyFn) => {
  const map = new Map();
  rows.forEach((r) => {
    const key = keyFn(r);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(r);
  });
  return map;
};

/* =========================================================
   COMPONENT
========================================================= */

export default function SalesRegister() {
  const { user } = useContext(AuthContext);
  const userLocationID = useMemo(() => getLocationID(user), [user]);

  /* ---------- FILTERS ---------- */

  const [fromDate, setFromDate] = useState(todayStr());
  const [toDate, setToDate] = useState(todayStr());
  const [locationID, setLocationID] = useState("");
  const [customerType, setCustomerType] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("");
  const [quickRange, setQuickRange] = useState("today");

  const applyQuickRange = (range) => {
    setQuickRange(range);
    const now = new Date();

    if (range === "today") {
      setFromDate(toDateInput(now));
      setToDate(toDateInput(now));
    } else if (range === "3days") {
      const from = new Date(now);
      from.setDate(from.getDate() - 2);
      setFromDate(toDateInput(from));
      setToDate(toDateInput(now));
    } else if (range === "7days") {
      const from = new Date(now);
      from.setDate(from.getDate() - 6);
      setFromDate(toDateInput(from));
      setToDate(toDateInput(now));
    }
  };

  /* ---------- UI ---------- */

  const [activeTab, setActiveTab] = useState("billwise");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  /* ---------- RAW DATA (loaded once) ---------- */

  const [allSales, setAllSales] = useState([]);
  const [productMap, setProductMap] = useState({});
  const [locations, setLocations] = useState([]);

  /* ---------- DERIVED (recomputed on filter change) ---------- */

  const [summary, setSummary] = useState({
    totalSales: 0,
    customerReturns: 0,
    netSales: 0,
    netProfit: 0,
    itemsSold: 0,
    invoiceCount: 0,
    avgInvoice: 0,
  });
  const [billwise, setBillwise] = useState([]);
  const [productwise, setProductwise] = useState([]);
  const [supplierwise, setSupplierwise] = useState([]);
  const [departmentwise, setDepartmentwise] = useState([]);
  const [dailyTrend, setDailyTrend] = useState([]);
  const [linesByReceipt, setLinesByReceipt] = useState({});

  const [expandedBill, setExpandedBill] = useState(null);

  /* =====================================================
     LOAD ALL DATA  (Firestore)
  ===================================================== */

  const loadAll = useCallback(async () => {
    setLoading(true);
    setError("");

    try {
      const [salesRows, productRows, locationRows] =
        await Promise.all([
          listCollection(SALES, {
            where: [["IsDelete", "==", 0]],
          }),
          listCollection(PRODUCTS, {
            where: [["IsDelete", "==", 0]],
          }),
          listCollection(COLLECTIONS.LOCATIONS, {
            where: [["IsDelete", "==", 0]],
          }),
        ]);

      const pMap = {};
      productRows.forEach((p) => {
        const code = String(
          pick(p, "ProductCode", "productcode") || ""
        ).trim();
        if (code) pMap[code] = p;
      });

      setAllSales(salesRows);
      setProductMap(pMap);
      setLocations(locationRows);
    } catch (err) {
      console.error("Sales register load error:", err);
      setError(
        err.message || "Failed to load sales register data."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  /* =====================================================
     RECOMPUTE AGGREGATES WHEN FILTERS CHANGE
  ===================================================== */

  useEffect(() => {
    if (allSales.length === 0 && Object.keys(productMap).length === 0) {
      return;
    }

    // 1. Flatten every sale into lines
    const allLines = flattenSales(allSales, productMap);

    // 2. Apply filters
    let lines = allLines;

    if (fromDate) {
      lines = lines.filter((l) => l.SaleDay && l.SaleDay >= fromDate);
    }

    if (toDate) {
      lines = lines.filter((l) => l.SaleDay && l.SaleDay <= toDate);
    }

    if (locationID) {
      lines = lines.filter(
        (l) => String(l.LocationID) === String(locationID)
      );
    }

    if (customerType) {
      lines = lines.filter(
        (l) => String(l.CustomerType) === String(customerType)
      );
    }

    if (paymentMethod) {
      const wanted = paymentMethod.toUpperCase();
      lines = lines.filter((l) =>
        l.PaymentMethod.includes(wanted)
      );
    }

    // 3. Summary
    const invoiceReceipts = new Set(lines.map((l) => l.Receipt));

    const totalSales = sumBy(lines, "GrossAmount");
    const netSales = sumBy(lines, "NetAmount");
    const netProfit = sumBy(lines, "Profit");
    const itemsSold = sumBy(lines, "Qty");
    const invoiceCount = invoiceReceipts.size;

    setSummary({
      totalSales,
      customerReturns: 0,
      netSales,
      netProfit,
      itemsSold,
      invoiceCount,
      avgInvoice:
        invoiceCount > 0 ? netSales / invoiceCount : 0,
    });

    // 4. Bill-wise
    const billGroups = groupBy(lines, (l) => l.Receipt);
    const billRows = [];
    billGroups.forEach((group, receipt) => {
      billRows.push({
        Receipt: receipt,
        SaleDate: group[0].SaleDate,
        CustomerName: group[0].CustomerName,
        Cashier: group[0].Cashier,
        Qty: sumBy(group, "Qty"),
        GrossAmount: sumBy(group, "GrossAmount"),
        LineDiscount: sumBy(group, "LineDiscount"),
        NetAmount: sumBy(group, "NetAmount"),
        CostAmount: sumBy(group, "CostAmount"),
        Profit: sumBy(group, "Profit"),
      });
    });
    billRows.sort((a, b) => {
      const da = new Date(a.SaleDate || 0).getTime();
      const db = new Date(b.SaleDate || 0).getTime();
      return db - da;
    });
    setBillwise(billRows);

    // 5. Line map keyed by receipt (for BillLines expansion)
    const lbr = {};
    lines.forEach((l) => {
      if (!lbr[l.Receipt]) lbr[l.Receipt] = [];
      lbr[l.Receipt].push(l);
    });
    setLinesByReceipt(lbr);

    // 6. Product-wise
    const productGroups = groupBy(lines, (l) => l.ProductCode);
    const productRows = [];
    productGroups.forEach((group, code) => {
      const bills = new Set(group.map((l) => l.Receipt)).size;
      productRows.push({
        ProductCode: code,
        ProductName: group[0].ProductName,
        BillsCount: bills,
        Qty: sumBy(group, "Qty"),
        GrossAmount: sumBy(group, "GrossAmount"),
        LineDiscount: sumBy(group, "LineDiscount"),
        NetAmount: sumBy(group, "NetAmount"),
        CostAmount: sumBy(group, "CostAmount"),
        Profit: sumBy(group, "Profit"),
      });
    });
    productRows.sort((a, b) => b.NetAmount - a.NetAmount);
    setProductwise(productRows);

    // 7. Supplier-wise
    const supplierGroups = groupBy(lines, (l) => l.SupplierName);
    const supplierRows = [];
    supplierGroups.forEach((group, name) => {
      const bills = new Set(group.map((l) => l.Receipt)).size;
      const products = new Set(group.map((l) => l.ProductCode)).size;
      supplierRows.push({
        SupplierName: name,
        BillsCount: bills,
        ProductsCount: products,
        Qty: sumBy(group, "Qty"),
        GrossAmount: sumBy(group, "GrossAmount"),
        LineDiscount: sumBy(group, "LineDiscount"),
        NetAmount: sumBy(group, "NetAmount"),
        Profit: sumBy(group, "Profit"),
      });
    });
    supplierRows.sort((a, b) => b.NetAmount - a.NetAmount);
    setSupplierwise(supplierRows);

    // 8. Department-wise
    const deptGroups = groupBy(lines, (l) => l.DepartmentName);
    const deptRows = [];
    deptGroups.forEach((group, name) => {
      const bills = new Set(group.map((l) => l.Receipt)).size;
      const products = new Set(group.map((l) => l.ProductCode)).size;
      deptRows.push({
        DepartmentName: name,
        BillsCount: bills,
        ProductsCount: products,
        Qty: sumBy(group, "Qty"),
        GrossAmount: sumBy(group, "GrossAmount"),
        LineDiscount: sumBy(group, "LineDiscount"),
        NetAmount: sumBy(group, "NetAmount"),
        Profit: sumBy(group, "Profit"),
      });
    });
    deptRows.sort((a, b) => b.NetAmount - a.NetAmount);
    setDepartmentwise(deptRows);

    // 9. Daily trend
    const dayGroups = groupBy(lines, (l) => l.SaleDay);
    const dayRows = [];
    dayGroups.forEach((group, day) => {
      dayRows.push({
        SaleDate: day,
        GrossAmount: sumBy(group, "GrossAmount"),
        NetAmount: sumBy(group, "NetAmount"),
        Qty: sumBy(group, "Qty"),
      });
    });
    dayRows.sort((a, b) =>
      a.SaleDate.localeCompare(b.SaleDate)
    );
    setDailyTrend(dayRows);
  }, [
    allSales,
    productMap,
    fromDate,
    toDate,
    locationID,
    customerType,
    paymentMethod,
  ]);

  /* =====================================================
     EXPORT CSV  (unchanged — reads derived state)
  ===================================================== */

  const exportCSV = () => {
    const rows = [];
    const addTitle = (t) => rows.push([t]);
    const addHeader = (h) => rows.push(h);
    const addRow = (v) => rows.push(v);

    addTitle(`Sales Register — ${fromDate} to ${toDate}`);
    addTitle("");

    addTitle("Summary");
    addHeader([
      "Total Sales",
      "Customer Returns",
      "Net Sales",
      "Net Profit",
      "Items Sold",
      "Invoices",
      "Avg Invoice",
    ]);
    addRow([
      summary.totalSales,
      summary.customerReturns,
      summary.netSales,
      summary.netProfit,
      summary.itemsSold,
      summary.invoiceCount,
      summary.avgInvoice,
    ]);
    addTitle("");

    addTitle("Bill-wise");
    addHeader([
      "Receipt",
      "Date",
      "Customer",
      "Cashier",
      "Qty",
      "Gross",
      "Net",
      "Discount",
      "Cost",
      "Profit",
    ]);
    billwise.forEach((b) =>
      addRow([
        b.Receipt,
        b.SaleDate,
        b.CustomerName,
        b.Cashier,
        b.Qty,
        b.GrossAmount,
        b.NetAmount,
        b.LineDiscount,
        b.CostAmount,
        b.Profit,
      ])
    );
    addTitle("");

    addTitle("Product-wise");
    addHeader([
      "Product Code",
      "Product Name",
      "Bills",
      "Qty",
      "Gross",
      "Net",
      "Discount",
      "Cost",
      "Profit",
    ]);
    productwise.forEach((p) =>
      addRow([
        p.ProductCode,
        p.ProductName,
        p.BillsCount,
        p.Qty,
        p.GrossAmount,
        p.NetAmount,
        p.LineDiscount,
        p.CostAmount,
        p.Profit,
      ])
    );
    addTitle("");

    addTitle("Supplier-wise");
    addHeader([
      "Supplier",
      "Bills",
      "Products",
      "Qty",
      "Gross",
      "Net",
      "Profit",
    ]);
    supplierwise.forEach((s) =>
      addRow([
        s.SupplierName,
        s.BillsCount,
        s.ProductsCount,
        s.Qty,
        s.GrossAmount,
        s.NetAmount,
        s.Profit,
      ])
    );
    addTitle("");

    addTitle("Department-wise");
    addHeader([
      "Department",
      "Bills",
      "Products",
      "Qty",
      "Gross",
      "Net",
      "Profit",
    ]);
    departmentwise.forEach((d) =>
      addRow([
        d.DepartmentName,
        d.BillsCount,
        d.ProductsCount,
        d.Qty,
        d.GrossAmount,
        d.NetAmount,
        d.Profit,
      ])
    );

    const csv = rows
      .map((r) =>
        r
          .map((cell) => {
            const s = String(cell ?? "");
            return /[",\n]/.test(s)
              ? `"${s.replace(/"/g, '""')}"`
              : s;
          })
          .join(",")
      )
      .join("\n");

    const blob = new Blob([csv], {
      type: "text/csv;charset=utf-8;",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `sales-register-${fromDate}-to-${toDate}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  /* =====================================================
     DERIVED UI VALUES
  ===================================================== */

  const profitMargin = useMemo(() => {
    if (!summary.netSales || summary.netSales <= 0) return 0;
    return (summary.netProfit / summary.netSales) * 100;
  }, [summary]);

  const maxTrend = useMemo(() => {
    if (!dailyTrend.length) return 1;
    return Math.max(
      ...dailyTrend.map((d) => Number(d.GrossAmount || 0)),
      1
    );
  }, [dailyTrend]);

  /* =====================================================
     RENDER
  ===================================================== */

  return (
    <div className="min-h-screen p-5" style={{ background: "#FAF7F0" }}>
      <div className="max-w-[1400px] mx-auto">
        {/* HEADER */}
        <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">
              Sales Register
            </h1>
            <p className="text-sm text-gray-500 mt-1">
              Bill-wise, product, supplier and department sales
            </p>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={loadAll}
              disabled={loading}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
            >
              {loading ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <RefreshCw size={16} />
              )}
              Refresh
            </button>
            <button
              type="button"
              onClick={exportCSV}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-sm font-medium text-gray-700 hover:bg-gray-50"
            >
              <Download size={16} />
              Export
            </button>
          </div>
        </div>

        {/* ERROR */}
        {error && (
          <div className="mb-5 px-4 py-3 rounded-xl bg-red-50 border border-red-200 text-sm text-red-700">
            {error}
          </div>
        )}

        {/* FILTERS */}
        <div className="rounded-2xl bg-white border border-gray-200 shadow-sm p-5 mb-5">
          <h2 className="text-base font-bold text-gray-900 mb-4">
            Filters
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-5">
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-gray-600 mb-2">
                Date Range
              </label>
              <div className="flex gap-1 mb-2">
                {[
                  { key: "today", label: "Today" },
                  { key: "3days", label: "3 Days" },
                  { key: "7days", label: "7 Days" },
                ].map((opt) => (
                  <button
                    key={opt.key}
                    type="button"
                    onClick={() => applyQuickRange(opt.key)}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-colors ${
                      quickRange === opt.key
                        ? "bg-amber-500 text-white"
                        : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                    }`}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              <div className="flex items-center gap-2">
                <Calendar size={16} className="text-gray-400" />
                <input
                  type="date"
                  value={fromDate}
                  onChange={(e) => {
                    setFromDate(e.target.value);
                    setQuickRange("custom");
                  }}
                  className="flex-1 h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                />
                <span className="text-gray-400 text-sm">–</span>
                <input
                  type="date"
                  value={toDate}
                  onChange={(e) => {
                    setToDate(e.target.value);
                    setQuickRange("custom");
                  }}
                  className="flex-1 h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-gray-600 mb-2">
                Location
              </label>
              <select
                value={locationID}
                onChange={(e) => setLocationID(e.target.value)}
                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
              >
                <option value="">All Locations</option>
                {locations.map((loc) => {
                  const id =
                    loc.LocationID ??
                    loc.locationID ??
                    loc.id ??
                    "";
                  const name =
                    loc.LocationName ??
                    loc.locationName ??
                    "";
                  return (
                    <option key={id} value={id}>
                      {name}
                    </option>
                  );
                })}
                {!locations.length && userLocationID > 0 && (
                  <option value={userLocationID}>
                    My Location ({userLocationID})
                  </option>
                )}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-gray-600 mb-2">
                Customer Type
              </label>
              <select
                value={customerType}
                onChange={(e) => setCustomerType(e.target.value)}
                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
              >
                {CUSTOMER_TYPES.map((c) => (
                  <option key={c.value} value={c.value}>
                    {c.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-5 mt-4">
            <div>
              <label className="block text-xs font-semibold text-gray-600 mb-2">
                Payment Method
              </label>
              <select
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
                className="w-full h-9 rounded-lg border border-gray-200 bg-white px-3 text-sm outline-none focus:ring-2 focus:ring-amber-200"
              >
                {PAYMENT_METHODS.map((p) => (
                  <option key={p.value} value={p.value}>
                    {p.label}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* SUMMARY CARDS */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-3 mb-5">
          <SummaryCard
            title="Total Sales"
            value={`Rs.${formatMoney(summary.totalSales)}`}
            sub={`${formatInt(summary.invoiceCount)} invoices`}
            icon={<DollarSign size={16} />}
            iconColor="text-gray-500"
          />
          <SummaryCard
            title="Customer Returns"
            value={`Rs.${formatMoney(summary.customerReturns)}`}
            sub="0.00 items returned"
            valueClass="text-red-500"
            icon={<RefreshCw size={16} />}
            iconColor="text-red-400"
          />
          <SummaryCard
            title="Net Sales"
            value={`Rs.${formatMoney(summary.netSales)}`}
            sub="Sales – returns"
            icon={<DollarSign size={16} />}
            iconColor="text-amber-500"
            highlight
          />
          <SummaryCard
            title="Net Profit"
            value={`Rs.${formatMoney(summary.netProfit)}`}
            sub={`${profitMargin.toFixed(2)}% margin`}
            subClass="text-green-600"
            icon={<TrendingUp size={16} />}
            iconColor="text-gray-500"
          />
          <SummaryCard
            title="Items Sold"
            value={formatNumber(summary.itemsSold)}
            sub="Total quantity"
            icon={<Package size={16} />}
            iconColor="text-gray-500"
          />
          <SummaryCard
            title="Avg per Invoice"
            value={`Rs.${formatMoney(summary.avgInvoice)}`}
            sub="Net average value"
            icon={<FileText size={16} />}
            iconColor="text-gray-500"
          />
        </div>

        {/* DAILY TREND */}
        {dailyTrend.length > 0 && (
          <div className="rounded-2xl bg-white border border-gray-200 shadow-sm p-5 mb-5">
            <h2 className="text-lg font-bold text-gray-900 mb-4">
              Daily Sales Trend
            </h2>
            <div className="flex items-end gap-3 h-52 border-l border-b border-dashed border-gray-200 pl-3 pb-3">
              {dailyTrend.map((d) => {
                const heightPct =
                  (Number(d.GrossAmount || 0) / maxTrend) * 100;
                return (
                  <div
                    key={String(d.SaleDate)}
                    className="flex-1 flex flex-col items-center justify-end h-full"
                  >
                    <div
                      className="w-full rounded-t-md bg-amber-500 hover:bg-amber-600 transition-all"
                      style={{
                        height: `${Math.max(4, heightPct)}%`,
                      }}
                      title={`Rs.${formatMoney(d.GrossAmount)}`}
                    />
                    <div className="text-[10px] text-gray-500 mt-1">
                      {new Date(d.SaleDate).toLocaleDateString(
                        "en-US",
                        { month: "short", day: "2-digit" }
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* TABS */}
        <div className="rounded-t-2xl bg-white border border-gray-200 border-b-0 shadow-sm px-3 pt-3 overflow-x-auto">
          <div className="flex items-center gap-1 min-w-max">
            {TABS.map((tab) => (
              <button
                key={tab.key}
                type="button"
                onClick={() => setActiveTab(tab.key)}
                className={`px-4 py-2 rounded-t-lg text-sm font-semibold transition-colors ${
                  activeTab === tab.key
                    ? "bg-amber-50 text-amber-700 border border-amber-200 border-b-white"
                    : "text-gray-600 hover:text-gray-900 hover:bg-gray-50"
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        {/* TAB CONTENT */}
        <div className="rounded-b-2xl bg-white border border-gray-200 shadow-sm p-5">
          {loading && (
            <div className="flex items-center justify-center py-16 text-gray-500">
              <Loader2 size={22} className="animate-spin mr-2" />
              Loading data…
            </div>
          )}

          {!loading && activeTab === "billwise" && (
            <BillwiseTable
              rows={billwise}
              expandedBill={expandedBill}
              setExpandedBill={setExpandedBill}
              linesByReceipt={linesByReceipt}
            />
          )}

          {!loading && activeTab === "productwise" && (
            <ProductwiseTable rows={productwise} />
          )}

          {!loading && activeTab === "supplierwise" && (
            <SupplierwiseTable rows={supplierwise} />
          )}

          {!loading && activeTab === "departmentwise" && (
            <DepartmentwiseTable rows={departmentwise} />
          )}
        </div>
      </div>
    </div>
  );
}

/* =========================================================
   SUMMARY CARD
========================================================= */

function SummaryCard({
  title,
  value,
  sub,
  subClass = "",
  valueClass = "",
  icon,
  iconColor,
  highlight,
}) {
  return (
    <div
      className={`rounded-2xl bg-white border shadow-sm p-4 ${
        highlight ? "border-amber-300" : "border-gray-200"
      }`}
    >
      <div className="flex items-center justify-between mb-2">
        <span className="text-xs font-semibold text-gray-600">
          {title}
        </span>
        <span className={iconColor}>{icon}</span>
      </div>
      <div
        className={`text-xl font-bold ${
          valueClass || "text-gray-900"
        }`}
      >
        {value}
      </div>
      <div className={`text-xs mt-1 ${subClass || "text-gray-500"}`}>
        {sub}
      </div>
    </div>
  );
}

/* =========================================================
   BILL-WISE TABLE
========================================================= */

function BillwiseTable({
  rows,
  expandedBill,
  setExpandedBill,
  linesByReceipt,
}) {
  if (!rows.length) {
    return (
      <EmptyState message="No bills found for the selected filters" />
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          <tr className="border-b border-gray-200 bg-gray-50">
            <Th className="w-10"></Th>
            <Th>Receipt</Th>
            <Th>Date</Th>
            <Th>Customer</Th>
            <Th>Cashier</Th>
            <Th align="right">Qty</Th>
            <Th align="right">Gross</Th>
            <Th align="right">Discount</Th>
            <Th align="right">Net</Th>
            <Th align="right">Cost</Th>
            <Th align="right">Profit</Th>
          </tr>
        </thead>
        <tbody>
          {rows.map((b) => {
            const expanded = expandedBill === b.Receipt;
            return (
              <React.Fragment key={b.Receipt}>
                <tr
                  className="border-b border-gray-100 hover:bg-amber-50/40 cursor-pointer"
                  onClick={() =>
                    setExpandedBill(expanded ? null : b.Receipt)
                  }
                >
                  <Td className="text-gray-400">
                    {expanded ? (
                      <ChevronDown size={16} />
                    ) : (
                      <ChevronRight size={16} />
                    )}
                  </Td>
                  <Td className="font-semibold text-gray-900">
                    {b.Receipt}
                  </Td>
                  <Td>{new Date(b.SaleDate).toLocaleString()}</Td>
                  <Td>{b.CustomerName || "—"}</Td>
                  <Td>{b.Cashier || "—"}</Td>
                  <Td align="right">{formatNumber(b.Qty)}</Td>
                  <Td align="right">
                    {formatMoney(b.GrossAmount)}
                  </Td>
                  <Td align="right" className="text-amber-700">
                    {formatMoney(b.LineDiscount)}
                  </Td>
                  <Td align="right" className="font-semibold">
                    {formatMoney(b.NetAmount)}
                  </Td>
                  <Td align="right" className="text-gray-500">
                    {formatMoney(b.CostAmount)}
                  </Td>
                  <Td
                    align="right"
                    className="font-semibold text-green-600"
                  >
                    {formatMoney(b.Profit)}
                  </Td>
                </tr>

                {expanded && (
                  <tr className="bg-amber-50/50">
                    <td colSpan={11} className="px-4 py-3">
                      <div className="text-xs font-semibold text-gray-600 mb-2">
                        Lines in receipt {b.Receipt}
                      </div>
                      <BillLines
                        lines={
                          (linesByReceipt &&
                            linesByReceipt[b.Receipt]) ||
                          []
                        }
                      />
                    </td>
                  </tr>
                )}
              </React.Fragment>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function BillLines({ lines }) {
  if (!lines || lines.length === 0) {
    return (
      <div className="text-xs text-gray-500">
        No line detail available.
      </div>
    );
  }

  return (
    <table className="w-full text-xs">
      <thead>
        <tr className="text-gray-500 border-b border-amber-200">
          <th className="text-left py-1">Code</th>
          <th className="text-left py-1">Product</th>
          <th className="text-right py-1">Qty</th>
          <th className="text-right py-1">Gross</th>
          <th className="text-right py-1">Disc %</th>
          <th className="text-right py-1">Disc Amt</th>
          <th className="text-right py-1">Net</th>
        </tr>
      </thead>
      <tbody>
        {lines.map((l, i) => {
          const discountPct =
            l.GrossAmount > 0
              ? (l.LineDiscount / l.GrossAmount) * 100
              : 0;

          return (
            <tr key={i} className="border-b border-amber-100/50">
              <td className="py-1">{l.ProductCode}</td>
              <td className="py-1">{l.ProductName}</td>
              <td className="py-1 text-right">
                {formatNumber(l.Qty)}
              </td>
              <td className="py-1 text-right">
                {formatMoney(l.GrossAmount)}
              </td>
              <td className="py-1 text-right">
                {formatNumber(discountPct)}
              </td>
              <td className="py-1 text-right">
                {formatMoney(l.LineDiscount)}
              </td>
              <td className="py-1 text-right font-semibold">
                {formatMoney(l.NetAmount)}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

