// CheckTemplate.jsx
// ============================================================
// Check Templates — Firestore version
// ------------------------------------------------------------
// Configure bank check printing templates.
//
// Firestore collections used:
//   - CheckTemplates  (per-template layout config)
//   - Accounts        (bank account assignment list)
//
// Operations:
//   - Load list / load one
//   - Create / update (createDoc / updateDocById)
//   - Soft delete
//
// Account IDs are stored as a string array in `AccountIDs` on
// each template document.
// ============================================================

import React, { useEffect, useState } from "react";

import {
  COLLECTIONS,
  listCollection,
  getDocById,
  createDoc,
  updateDocById,
  softDeleteDoc,
} from "../lib/firestore.js";

/* =========================================================
   DEFAULTS
========================================================= */

const defaultTemplate = {
  templateName: "BOC",
  bankName: "BOC",

  checkWidth: 210,
  checkHeight: 102,
  stubWidth: 30,

  showCounterfoil: true,

  dateFontSize: 14,
  payeeFontSize: 14,
  amountWordsFontSize: 10,
  amountWordsLineHeight: 1.4,
  amountNumbersFontSize: 16,

  dateX: 160,
  dateY: 12,

  payeeX: 60,
  payeeY: 32,

  amountWordsX: 60,
  amountWordsY: 45,

  amountX: 160,
  amountY: 60,

  payeeLabel: "Pay",
  amountLabel: "Amount",
};

/* =========================================================
   NORMALIZERS
========================================================= */

const normalizeTemplate = (raw) => {
  if (!raw) return null;

  return {
    TemplateID: raw.id,

    TemplateName: raw.TemplateName ?? "",
    BankName: raw.BankName ?? "",

    CheckWidth: Number(raw.CheckWidth ?? defaultTemplate.checkWidth),
    CheckHeight: Number(raw.CheckHeight ?? defaultTemplate.checkHeight),
    StubWidth: Number(raw.StubWidth ?? defaultTemplate.stubWidth),

    ShowCounterfoil: Boolean(
      raw.ShowCounterfoil ?? defaultTemplate.showCounterfoil
    ),

    DateFontSize: Number(raw.DateFontSize ?? defaultTemplate.dateFontSize),
    PayeeFontSize: Number(raw.PayeeFontSize ?? defaultTemplate.payeeFontSize),
    AmountWordsFontSize: Number(
      raw.AmountWordsFontSize ?? defaultTemplate.amountWordsFontSize
    ),
    AmountWordsLineHeight: Number(
      raw.AmountWordsLineHeight ?? defaultTemplate.amountWordsLineHeight
    ),
    AmountNumbersFontSize: Number(
      raw.AmountNumbersFontSize ?? defaultTemplate.amountNumbersFontSize
    ),

    DateX: Number(raw.DateX ?? defaultTemplate.dateX),
    DateY: Number(raw.DateY ?? defaultTemplate.dateY),

    PayeeX: Number(raw.PayeeX ?? defaultTemplate.payeeX),
    PayeeY: Number(raw.PayeeY ?? defaultTemplate.payeeY),

    AmountWordsX: Number(raw.AmountWordsX ?? defaultTemplate.amountWordsX),
    AmountWordsY: Number(raw.AmountWordsY ?? defaultTemplate.amountWordsY),

    AmountX: Number(raw.AmountX ?? defaultTemplate.amountX),
    AmountY: Number(raw.AmountY ?? defaultTemplate.amountY),

    PayeeLabel: raw.PayeeLabel ?? defaultTemplate.payeeLabel,
    AmountLabel: raw.AmountLabel ?? defaultTemplate.amountLabel,

    AccountIDs: Array.isArray(raw.AccountIDs)
      ? raw.AccountIDs.map(String)
      : [],
  };
};

/** Convert internal camelCase form state → Firestore PascalCase doc. */
const toFirestorePayload = (form, accountIDs) => ({
  TemplateName: form.templateName.trim(),
  BankName: form.bankName.trim(),

  CheckWidth: Number(form.checkWidth),
  CheckHeight: Number(form.checkHeight),
  StubWidth: Number(form.stubWidth),

  ShowCounterfoil: Boolean(form.showCounterfoil),

  DateFontSize: Number(form.dateFontSize),
  PayeeFontSize: Number(form.payeeFontSize),
  AmountWordsFontSize: Number(form.amountWordsFontSize),
  AmountWordsLineHeight: Number(form.amountWordsLineHeight),
  AmountNumbersFontSize: Number(form.amountNumbersFontSize),

  DateX: Number(form.dateX),
  DateY: Number(form.dateY),

  PayeeX: Number(form.payeeX),
  PayeeY: Number(form.payeeY),

  AmountWordsX: Number(form.amountWordsX),
  AmountWordsY: Number(form.amountWordsY),

  AmountX: Number(form.amountX),
  AmountY: Number(form.amountY),

  PayeeLabel: form.payeeLabel,
  AmountLabel: form.amountLabel,

  AccountIDs: accountIDs.map(String),
});

/* =========================================================
   COMPONENT
========================================================= */

export default function CheckTemplate() {
  const [templates, setTemplates] = useState([]);
  const [accounts, setAccounts] = useState([]);

  const [selectedTemplateId, setSelectedTemplateId] = useState(null);

  const [form, setForm] = useState(defaultTemplate);

  const [selectedAccounts, setSelectedAccounts] = useState([]);

  const [loading, setLoading] = useState(false);

  const [message, setMessage] = useState("");

  const [activeElement, setActiveElement] = useState(null);

  /* =========================================================
     LOAD
  ========================================================= */

  useEffect(() => {
    loadTemplates();
    loadAccounts();
  }, []);

  async function loadTemplates() {
    try {
      const rows = await listCollection(COLLECTIONS.CHECK_TEMPLATES, {
        where: [["IsDelete", "==", 0]],
      });

      setTemplates(
        rows
          .map(normalizeTemplate)
          .filter(Boolean)
          .sort((a, b) =>
            String(a.TemplateName).localeCompare(String(b.TemplateName))
          )
      );
    } catch (error) {
      console.error("LOAD TEMPLATES ERROR:", error);
    }
  }

  async function loadAccounts() {
    try {
      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });

      setAccounts(
        rows
          .map((a) => ({
            AccountID: a.id,
            AccountName: a.AccountName ?? a.name ?? "Unnamed Account",
            AccountNumber: a.AccountNumber ?? "",
            BankName: a.BankName ?? "",
          }))
          .sort((a, b) => a.AccountName.localeCompare(b.AccountName))
      );
    } catch (error) {
      console.error("LOAD ACCOUNTS ERROR:", error);
    }
  }

  /* =========================================================
     FORM
  ========================================================= */

  function updateField(name, value) {
    setForm((prev) => ({ ...prev, [name]: value }));
  }

  function numberField(name, value) {
    updateField(name, Number(value));
  }

  /* =========================================================
     ACCOUNT SELECTION
  ========================================================= */

  function toggleAccount(accountId) {
    const id = String(accountId);

    setSelectedAccounts((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  /* =========================================================
     NEW TEMPLATE
  ========================================================= */

  function newTemplate() {
    setSelectedTemplateId(null);
    setForm({ ...defaultTemplate });
    setSelectedAccounts([]);
    setMessage("");
  }

  /* =========================================================
     EDIT TEMPLATE
  ========================================================= */

  async function editTemplate(id) {
    try {
      setLoading(true);
      setMessage("");

      const raw = await getDocById(COLLECTIONS.CHECK_TEMPLATES, id);

      if (!raw) {
        alert("Template not found");
        return;
      }

      const t = normalizeTemplate(raw);

      setSelectedTemplateId(t.TemplateID);

      setForm({
        templateName: t.TemplateName,
        bankName: t.BankName,

        checkWidth: t.CheckWidth,
        checkHeight: t.CheckHeight,
        stubWidth: t.StubWidth,

        showCounterfoil: t.ShowCounterfoil,

        dateFontSize: t.DateFontSize,
        payeeFontSize: t.PayeeFontSize,
        amountWordsFontSize: t.AmountWordsFontSize,
        amountWordsLineHeight: t.AmountWordsLineHeight,
        amountNumbersFontSize: t.AmountNumbersFontSize,

        dateX: t.DateX,
        dateY: t.DateY,

        payeeX: t.PayeeX,
        payeeY: t.PayeeY,

        amountWordsX: t.AmountWordsX,
        amountWordsY: t.AmountWordsY,

        amountX: t.AmountX,
        amountY: t.AmountY,

        payeeLabel: t.PayeeLabel,
        amountLabel: t.AmountLabel,
      });

      setSelectedAccounts(t.AccountIDs || []);
    } catch (error) {
      console.error("EDIT TEMPLATE ERROR:", error);
      alert(error.message || "Unable to load template");
    } finally {
      setLoading(false);
    }
  }

  /* =========================================================
     SAVE
  ========================================================= */

  async function saveTemplate() {
    if (!form.templateName.trim()) {
      alert("Please enter template name");
      return;
    }

    setLoading(true);
    setMessage("");

    try {
      const username =
        localStorage.getItem("username") ||
        localStorage.getItem("Username") ||
        "ADMIN";

      const payload = toFirestorePayload(form, selectedAccounts);

      if (selectedTemplateId) {
        await updateDocById(
          COLLECTIONS.CHECK_TEMPLATES,
          selectedTemplateId,
          payload,
          { username }
        );
        setMessage("Template updated successfully");
      } else {
        const created = await createDoc(
          COLLECTIONS.CHECK_TEMPLATES,
          payload,
          { username }
        );
        setMessage("Template saved successfully");
        setSelectedTemplateId(created.id);
      }

      await loadTemplates();
    } catch (error) {
      console.error("SAVE TEMPLATE ERROR:", error);
      alert(error.message || "Unable to save template");
    } finally {
      setLoading(false);
    }
  }

  /* =========================================================
     DELETE
  ========================================================= */

  async function deleteTemplate() {
    if (!selectedTemplateId) return;

    if (!window.confirm("Delete this check template?")) return;

    try {
      setLoading(true);

      const username =
        localStorage.getItem("username") ||
        localStorage.getItem("Username") ||
        "ADMIN";

      await softDeleteDoc(COLLECTIONS.CHECK_TEMPLATES, selectedTemplateId, {
        username,
      });

      newTemplate();
      await loadTemplates();
    } catch (error) {
      console.error("DELETE TEMPLATE ERROR:", error);
      alert(error.message || "Unable to delete template");
    } finally {
      setLoading(false);
    }
  }

  /* =========================================================
     POSITION UPDATE (used by PreviewElement onClick)
  ========================================================= */

  function moveElement(element, x, y) {
    if (element === "date") {
      setForm((prev) => ({ ...prev, dateX: x, dateY: y }));
    }
    if (element === "payee") {
      setForm((prev) => ({ ...prev, payeeX: x, payeeY: y }));
    }
    if (element === "words") {
      setForm((prev) => ({ ...prev, amountWordsX: x, amountWordsY: y }));
    }
    if (element === "amount") {
      setForm((prev) => ({ ...prev, amountX: x, amountY: y }));
    }
  }

  /* =========================================================
     RENDER
  ========================================================= */

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      {/* HEADER */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Check Templates</h1>
          <p className="text-gray-500 mt-1">
            Configure bank check printing templates
          </p>
        </div>

        <button
          onClick={newTemplate}
          className="bg-amber-500 hover:bg-amber-600 text-white px-5 py-3 rounded-lg font-semibold"
        >
          + New Template
        </button>
      </div>

      {/* TEMPLATE SELECTOR */}
      <div className="bg-white border rounded-xl p-5 mb-6">
        <div className="flex flex-wrap gap-3">
          {templates.map((template) => (
            <button
              key={template.TemplateID}
              onClick={() => editTemplate(template.TemplateID)}
              className={`px-5 py-3 rounded-lg border ${
                selectedTemplateId === template.TemplateID
                  ? "bg-amber-500 text-white border-amber-500"
                  : "bg-white hover:bg-gray-50"
              }`}
            >
              {template.TemplateName}
            </button>
          ))}

          {templates.length === 0 && (
            <p className="text-sm text-gray-500">
              No templates yet. Click "New Template" to create one.
            </p>
          )}
        </div>
      </div>

      {/* TEMPLATE INFORMATION */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <h2 className="text-xl font-semibold mb-5">Template Information</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <div>
            <label className="block text-sm font-medium mb-2">
              Template Name
            </label>
            <input
              value={form.templateName}
              onChange={(e) => updateField("templateName", e.target.value)}
              className="w-full border rounded-lg px-4 py-3"
              placeholder="BOC"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Bank Name</label>
            <input
              value={form.bankName}
              onChange={(e) => updateField("bankName", e.target.value)}
              className="w-full border rounded-lg px-4 py-3"
              placeholder="Bank name"
            />
          </div>
        </div>
      </div>

      {/* ASSIGNED BANK ACCOUNTS */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <div className="flex justify-between mb-5">
          <div>
            <h2 className="text-xl font-semibold">Assigned Bank Accounts</h2>
            <p className="text-sm text-gray-500 mt-1">
              Select accounts that will use this template
            </p>
          </div>
        </div>

        <div className="border rounded-xl p-5 grid grid-cols-1 md:grid-cols-2 gap-3">
          {accounts.map((account) => {
            const id = String(account.AccountID);
            const checked = selectedAccounts.includes(id);

            return (
              <label
                key={id}
                className={`flex items-start gap-3 p-3 rounded-lg cursor-pointer ${
                  checked ? "bg-amber-50" : "hover:bg-gray-50"
                }`}
              >
                <input
                  type="checkbox"
                  checked={checked}
                  onChange={() => toggleAccount(id)}
                  className="mt-1 h-4 w-4 accent-amber-500"
                />

                <div>
                  <div className="font-medium">{account.AccountName}</div>
                  <div className="text-sm text-gray-500">
                    {account.AccountNumber}
                    {account.BankName && ` (${account.BankName})`}
                  </div>
                </div>
              </label>
            );
          })}

          {accounts.length === 0 && (
            <p className="col-span-2 text-sm text-gray-500">
              No accounts available.
            </p>
          )}
        </div>
      </div>

      {/* GLOBAL SETTINGS */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <h2 className="text-xl font-semibold mb-5">Global Settings</h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
          <NumberInput
            label="Check Width (mm)"
            value={form.checkWidth}
            onChange={(v) => numberField("checkWidth", v)}
          />

          <NumberInput
            label="Check Height (mm)"
            value={form.checkHeight}
            onChange={(v) => numberField("checkHeight", v)}
          />

          <NumberInput
            label="Stub Width (mm)"
            value={form.stubWidth}
            onChange={(v) => numberField("stubWidth", v)}
          />
        </div>

        <div className="mt-5">
          <label className="flex items-center gap-3 cursor-pointer">
            <input
              type="checkbox"
              checked={form.showCounterfoil}
              onChange={(e) => updateField("showCounterfoil", e.target.checked)}
              className="h-5 w-5 accent-amber-500"
            />
            <span className="font-medium">Show Counterfoil / Stub</span>
          </label>
        </div>
      </div>

      {/* FONT SETTINGS */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <h2 className="text-xl font-semibold mb-5">Font Sizes (pixels)</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <NumberInput
            label="Date Font Size"
            value={form.dateFontSize}
            onChange={(v) => numberField("dateFontSize", v)}
          />

          <NumberInput
            label="Payee Font Size"
            value={form.payeeFontSize}
            onChange={(v) => numberField("payeeFontSize", v)}
          />

          <NumberInput
            label="Amount Words Font Size"
            value={form.amountWordsFontSize}
            onChange={(v) => numberField("amountWordsFontSize", v)}
          />

          <NumberInput
            label="Amount Words Line Height"
            value={form.amountWordsLineHeight}
            step="0.1"
            onChange={(v) => numberField("amountWordsLineHeight", v)}
          />

          <NumberInput
            label="Amount Numbers Font Size"
            value={form.amountNumbersFontSize}
            onChange={(v) => numberField("amountNumbersFontSize", v)}
          />
        </div>
      </div>

      {/* LABEL SETTINGS */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <h2 className="text-xl font-semibold mb-5">Check Labels</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <TextInput
            label="Payee Label"
            value={form.payeeLabel}
            onChange={(v) => updateField("payeeLabel", v)}
          />

          <TextInput
            label="Amount Label"
            value={form.amountLabel}
            onChange={(v) => updateField("amountLabel", v)}
          />
        </div>
      </div>

      {/* POSITION SETTINGS */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <h2 className="text-xl font-semibold mb-5">Element Positions</h2>

        <p className="text-sm text-gray-500 mb-5">
          All positions are in millimeters.
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <PositionBox
            title="Date"
            x={form.dateX}
            y={form.dateY}
            onX={(v) => numberField("dateX", v)}
            onY={(v) => numberField("dateY", v)}
          />

          <PositionBox
            title="Payee"
            x={form.payeeX}
            y={form.payeeY}
            onX={(v) => numberField("payeeX", v)}
            onY={(v) => numberField("payeeY", v)}
          />

          <PositionBox
            title="Amount in Words"
            x={form.amountWordsX}
            y={form.amountWordsY}
            onX={(v) => numberField("amountWordsX", v)}
            onY={(v) => numberField("amountWordsY", v)}
          />

          <PositionBox
            title="Amount"
            x={form.amountX}
            y={form.amountY}
            onX={(v) => numberField("amountX", v)}
            onY={(v) => numberField("amountY", v)}
          />
        </div>
      </div>

      {/* PREVIEW */}
      <div className="bg-white border rounded-xl p-6 mb-6">
        <div className="text-center mb-5">
          <h2 className="text-xl font-semibold">
            Template: {form.templateName}
          </h2>
          <p className="text-gray-500">Bank: {form.bankName}</p>
          <p className="text-sm text-gray-400">
            All values in millimeters
          </p>
        </div>

        <div className="overflow-auto border rounded-lg p-8 bg-gray-50">
          <CheckPreview
            form={form}
            activeElement={activeElement}
            setActiveElement={setActiveElement}
          />
        </div>
      </div>

      {/* BUTTONS */}
      <div className="flex justify-end gap-3">
        {selectedTemplateId && (
          <button
            onClick={deleteTemplate}
            disabled={loading}
            className="px-5 py-3 border border-red-300 text-red-600 rounded-lg hover:bg-red-50 disabled:opacity-50"
          >
            Delete
          </button>
        )}

        <button
          onClick={newTemplate}
          disabled={loading}
          className="px-5 py-3 border rounded-lg disabled:opacity-50"
        >
          Reset
        </button>

        <button
          onClick={saveTemplate}
          disabled={loading}
          className="px-6 py-3 bg-amber-500 hover:bg-amber-600 text-white rounded-lg font-semibold disabled:opacity-50"
        >
          {loading
            ? "Saving..."
            : selectedTemplateId
            ? "Update Template"
            : "Save Template"}
        </button>
      </div>

      {message && (
        <div className="mt-4 text-center text-green-600">{message}</div>
      )}
    </div>
  );
}

/* =========================================================
   NUMBER INPUT
========================================================= */

function NumberInput({ label, value, onChange, step = "1" }) {
  return (
    <div>
      <label className="block text-sm font-medium mb-2">{label}</label>
      <input
        type="number"
        step={step}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full border rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-amber-400"
      />
    </div>
  );
}

/* =========================================================
   TEXT INPUT
========================================================= */

function TextInput({ label, value, onChange }) {
  return (
    <div>
      <label className="block text-sm font-medium mb-2">{label}</label>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full border rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-amber-400"
      />
    </div>
  );
}

/* =========================================================
   POSITION BOX
========================================================= */

function PositionBox({ title, x, y, onX, onY }) {
  return (
    <div className="border rounded-xl p-4">
      <h3 className="font-semibold mb-4">{title}</h3>

      <div className="grid grid-cols-2 gap-4">
        <NumberInput
          label="X Position"
          value={x}
          onChange={onX}
          step="0.1"
        />

        <NumberInput
          label="Y Position"
          value={y}
          onChange={onY}
          step="0.1"
        />
      </div>
    </div>
  );
}

/* =========================================================
   CHECK PREVIEW
========================================================= */

function CheckPreview({ form, setActiveElement }) {
  const scale = 3;

  const width = Number(form.checkWidth) * scale;
  const height = Number(form.checkHeight) * scale;

  return (
    <div
      className="relative bg-white border-2 border-gray-300 shadow-xl mx-auto"
      style={{ width, height }}
    >
      {/* BANK */}
      <div className="absolute left-5 top-4 font-bold text-lg">
        {form.bankName || "BANK NAME"}
      </div>

      {/* DATE */}
      <PreviewElement
        name="date"
        label="Date"
        x={form.dateX}
        y={form.dateY}
        scale={scale}
        fontSize={form.dateFontSize}
        onClick={() => setActiveElement("date")}
      >
        02/09/2026
      </PreviewElement>

      {/* PAYEE */}
      <PreviewElement
        name="payee"
        label={form.payeeLabel}
        x={form.payeeX}
        y={form.payeeY}
        scale={scale}
        fontSize={form.payeeFontSize}
        onClick={() => setActiveElement("payee")}
      >
        TEST SUPPLIER PVT LTD
      </PreviewElement>

      {/* AMOUNT WORDS */}
      <PreviewElement
        name="words"
        label="Amount in Words"
        x={form.amountWordsX}
        y={form.amountWordsY}
        scale={scale}
        fontSize={form.amountWordsFontSize}
        onClick={() => setActiveElement("words")}
        width={150}
      >
        Thirty Five Thousand Rupees Only
      </PreviewElement>

      {/* AMOUNT */}
      <PreviewElement
        name="amount"
        label={form.amountLabel}
        x={form.amountX}
        y={form.amountY}
        scale={scale}
        fontSize={form.amountNumbersFontSize}
        onClick={() => setActiveElement("amount")}
      >
        Rs. 35,000.00
      </PreviewElement>

      {/* OR BEARER */}
      <div
        className="absolute border-b-2 border-gray-500"
        style={{
          right: 20,
          top: height * 0.35,
          width: 130,
        }}
      >
        <span className="text-xs">Or Bearer</span>
      </div>

      {/* SIGNATURE */}
      <div className="absolute bottom-6 right-8 text-xs text-gray-500">
        Authorized Signature
      </div>

      {/* COUNTERFOIL */}
      {form.showCounterfoil && (
        <div
          className="absolute left-0 top-0 h-full border-r-2 border-dashed border-gray-400 bg-gray-50"
          style={{ width: Number(form.stubWidth) * scale }}
        >
          <div className="p-3 text-[10px] space-y-2">
            <div className="font-bold">COUNTERFOIL</div>
            <div>Check: 000123</div>
            <div>Date: 02/09/2026</div>
            <div>Pay: TEST SUPPLIER</div>
            <div>Amt: Rs. 35000.00</div>
          </div>
        </div>
      )}
    </div>
  );
}

/* =========================================================
   PREVIEW ELEMENT
========================================================= */

function PreviewElement({
  x,
  y,
  scale,
  fontSize,
  label,
  children,
  onClick,
  width,
}) {
  return (
    <div
      onClick={onClick}
      className="absolute cursor-pointer border border-transparent hover:border-blue-400 hover:bg-blue-50/30 p-1 rounded"
      style={{
        left: Number(x) * scale,
        top: Number(y) * scale,
        fontSize: Number(fontSize),
        width: width ? width * scale : "auto",
      }}
    >
      <div className="text-xs text-gray-500">{label}</div>
      <div className="font-semibold whitespace-nowrap">{children}</div>
    </div>
  );
}