// GiftVoucher.jsx
// ============================================================
// Gift Voucher Management — Firestore version
// ------------------------------------------------------------
// Firestore collections used:
//   - GiftVoucherGroups       (group definitions)
//   - GiftVoucherBooks        (generated books)
//   - GiftVouchers            (individual vouchers)
//   - GiftVoucherTransfers    (transfer records)
//   - VoucherTemplates        (layout for printing)
//   - Locations               (location dropdown)
//
// Multi-doc operations:
//   - generateVouchers() → transaction: 1 book + N vouchers
//   - transferVouchers() → transaction: 1 transfer + N voucher updates
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  doc,
  collection,
  serverTimestamp,
  writeBatch,
} from "firebase/firestore";

import {
  Gift,
  Ticket,
  Barcode,
  ArrowRightLeft,
  Plus,
  Search,
  Printer,
  RefreshCw,
  History,
  X,
} from "lucide-react";

import {
  COLLECTIONS,
  listCollection,
  getDocById,
  createDoc,
  runFirestoreTransaction,
} from "../lib/firestore";
import { db } from "../firebase.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   CONSTANTS
====================================================== */

const GROUPS = "GiftVoucherGroups";
const BOOKS = "GiftVoucherBooks";
const VOUCHERS = "GiftVouchers";
const TRANSFERS = "GiftVoucherTransfers";

/* ======================================================
   HELPERS
====================================================== */

const pad = (n, len = 0) => String(n).padStart(len, "0");

const normalizeLocation = (raw) => ({
  LocationID: raw.id,
  LocationCode: raw.LocationCode ?? "",
  LocationName: raw.LocationName ?? raw.name ?? "",
});

const normalizeGroup = (raw) => ({
  GiftVoucherGroupID: raw.id,
  GroupCode: raw.GroupCode ?? "",
  GroupName: raw.GroupName ?? "",
  BasedOn: raw.BasedOn ?? "Book Serial",
  VoucherValue: Number(raw.VoucherValue ?? 0),
  ValidityDays: Number(raw.ValidityDays ?? 0),
  PercentageOfCoupon: Number(raw.PercentageOfCoupon ?? 0),
  VoucherType: raw.VoucherType ?? "Voucher",
});

const normalizeVoucher = (raw) => ({
  GiftVoucherID: raw.id,
  VoucherNo: raw.VoucherNo ?? "",
  VoucherSerial: raw.VoucherSerial ?? "",
  VoucherValue: Number(raw.VoucherValue ?? 0),
  VoucherType: raw.VoucherType ?? "Voucher",
  BookCode: raw.BookCode ?? "",
  BookName: raw.BookName ?? "",
  Status: raw.Status ?? "Available",
  ExpiryDate: raw.ExpiryDate ?? null,
  LocationID: raw.LocationID ?? "",
  VoucherTemplateID: raw.VoucherTemplateID ?? null,
});

/* ======================================================
   COMPONENT
====================================================== */

export default function GiftVoucher() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  /* ---------- TABS ---------- */
  const [activeTab, setActiveTab] = useState("generation");
  const [voucherType, setVoucherType] = useState("Voucher");

  /* ---------- DATA ---------- */
  const [groups, setGroups] = useState([]);
  const [vouchers, setVouchers] = useState([]);
  const [selectedVouchers, setSelectedVouchers] = useState([]);

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  /* ---------- LOCATIONS ---------- */
  const [locations, setLocations] = useState([]);
  const [locationsLoading, setLocationsLoading] = useState(false);

  /* ---------- GROUP FORM ---------- */
  const [groupForm, setGroupForm] = useState({
    groupCode: "",
    groupName: "",
    basedOn: "Book Serial",
    voucherValue: "",
    validityDays: "",
    percentageOfCoupon: "",
  });

  /* ---------- BOOK FORM ---------- */
  const [bookForm, setBookForm] = useState({
    groupId: "",
    bookCode: "",
    bookName: "",
    startingNo: "1",
    serialLength: "8",
    noOfVouchers: "10",
    voucherPrefix: "",
    voucherValue: "",
    validityDays: "",
  });

  /* ---------- SEARCH ---------- */
  const [search, setSearch] = useState({
    voucherNo: "",
    serial: "",
    status: "",
  });

  /* ---------- TRANSFER ---------- */
  const [transfer, setTransfer] = useState({
    documentNo: "",
    toLocationId: "",
    reference: "",
    remark: "",
  });

  /* ---------- TRANSFER HISTORY ---------- */
  const [transferHistory, setTransferHistory] = useState([]);
  const [showHistory, setShowHistory] = useState(false);
  const [transferDetails, setTransferDetails] = useState([]);
  const [showTransferDetails, setShowTransferDetails] = useState(false);

  /* ======================================================
     LOAD GROUPS
  ====================================================== */

  const loadGroups = useCallback(async () => {
    try {
      const rows = await listCollection(GROUPS, {
        where: [["IsDelete", "==", 0]],
      });

      setGroups(
        rows
          .map(normalizeGroup)
          .sort((a, b) =>
            String(a.GroupCode).localeCompare(String(b.GroupCode))
          )
      );
    } catch (err) {
      console.error("LOAD GROUPS ERROR:", err);
      setMessage("Unable to load voucher groups");
    }
  }, []);

  /* ======================================================
     LOAD LOCATIONS
  ====================================================== */

  const loadLocations = useCallback(async () => {
    try {
      setLocationsLoading(true);

      const rows = await listCollection(COLLECTIONS.LOCATIONS, {
        where: [["IsDelete", "==", 0]],
      });

      const list = rows
        .map(normalizeLocation)
        .filter((l) => l.LocationID)
        .sort((a, b) => a.LocationName.localeCompare(b.LocationName));

      setLocations(list);

      if (list.length === 0) {
        setMessage("No locations available");
      }
    } catch (err) {
      console.error("LOAD LOCATIONS ERROR:", err);
      setMessage("Unable to load locations.");
    } finally {
      setLocationsLoading(false);
    }
  }, []);

  /* ======================================================
     LOAD VOUCHERS
  ====================================================== */

  const loadVouchers = useCallback(async () => {
    try {
      setLoading(true);

      const rows = await listCollection(VOUCHERS, {
        where: [["IsDelete", "==", 0]],
      });

      let filtered = rows.map(normalizeVoucher);

      // Tab-specific defaults
      if (activeTab === "transfer") {
        filtered = filtered.filter((v) => v.Status === "Available");
      }

      // Client-side filters
      const voucherNoQ = search.voucherNo.trim().toLowerCase();
      const serialQ = search.serial.trim().toLowerCase();

      if (voucherNoQ) {
        filtered = filtered.filter((v) =>
          v.VoucherNo.toLowerCase().includes(voucherNoQ)
        );
      }
      if (serialQ) {
        filtered = filtered.filter((v) =>
          v.VoucherSerial.toLowerCase().includes(serialQ)
        );
      }
      if (search.status) {
        filtered = filtered.filter((v) => v.Status === search.status);
      }

      setVouchers(filtered);
    } catch (err) {
      console.error("LOAD VOUCHERS ERROR:", err);
      setMessage("Unable to load vouchers");
    } finally {
      setLoading(false);
    }
  }, [activeTab, search]);

  /* ======================================================
     LOAD TRANSFER HISTORY
  ====================================================== */

  const loadTransferHistory = useCallback(async () => {
    try {
      const rows = await listCollection(TRANSFERS, {
        where: [["IsDelete", "==", 0]],
      });

      setTransferHistory(
        rows
          .map((r) => ({
            GiftVoucherTransferID: r.id,
            DocumentNo: r.DocumentNo ?? "",
            FromLocationID: r.FromLocationID ?? "",
            ToLocation: r.ToLocationID ?? "",
            Reference: r.Reference ?? "",
            Remark: r.Remark ?? "",
            VoucherCount: Number(r.VoucherCount ?? 0),
            TotalValue: Number(r.TotalValue ?? 0),
            TransferDate: r.TransferDate ?? null,
            CreatedBy: r.CreatedBy ?? "",
            Vouchers: r.Vouchers ?? [],
          }))
          .sort((a, b) => {
            const da = new Date(a.TransferDate || 0).getTime();
            const db = new Date(b.TransferDate || 0).getTime();
            return db - da;
          })
      );
    } catch (err) {
      console.error("LOAD TRANSFER HISTORY ERROR:", err);
      setMessage("Unable to load transfer history");
    }
  }, []);

  /* ======================================================
     LOAD TRANSFER DETAILS
  ====================================================== */

  const loadTransferDetails = async (transferId) => {
    try {
      const row = await getDocById(TRANSFERS, transferId);
      if (!row) return;

      setTransferDetails(row.Vouchers || []);
      setShowTransferDetails(true);
    } catch (err) {
      console.error("LOAD TRANSFER DETAILS ERROR:", err);
      setMessage("Unable to load transfer details");
    }
  };

  /* ======================================================
     INITIAL LOAD
  ====================================================== */

  useEffect(() => {
    loadGroups();
    loadLocations();
  }, [loadGroups, loadLocations]);

  useEffect(() => {
    if (activeTab === "transfer") {
      loadVouchers();
      setSelectedVouchers([]);
      loadTransferHistory();
    } else if (activeTab === "master" || activeTab === "barcode") {
      loadVouchers();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab]);

  /* ======================================================
     FORM HANDLERS
  ====================================================== */

  const handleGroupChange = (e) => {
    setGroupForm({ ...groupForm, [e.target.name]: e.target.value });
  };

  const handleBookChange = (e) => {
    setBookForm({ ...bookForm, [e.target.name]: e.target.value });
  };

  /* ======================================================
     SAVE GROUP
  ====================================================== */

  const saveGroup = async () => {
    if (!groupForm.groupCode) return alert("Enter group code");
    if (!groupForm.groupName) return alert("Enter group name");

    try {
      setLoading(true);

      await createDoc(
        GROUPS,
        {
          GroupCode: groupForm.groupCode.trim(),
          GroupName: groupForm.groupName.trim(),
          BasedOn: groupForm.basedOn,
          VoucherValue: Number(groupForm.voucherValue || 0),
          ValidityDays: Number(groupForm.validityDays || 0),
          PercentageOfCoupon: Number(groupForm.percentageOfCoupon || 0),
          VoucherType: voucherType,
          IsDelete: 0,
        },
        { username }
      );

      alert("Gift voucher group saved successfully");

      setGroupForm({
        groupCode: "",
        groupName: "",
        basedOn: "Book Serial",
        voucherValue: "",
        validityDays: "",
        percentageOfCoupon: "",
      });

      await loadGroups();
    } catch (err) {
      console.error("SAVE GROUP ERROR:", err);
      alert(err.message || "Unable to save group");
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     GENERATE VOUCHERS
     ------------------------------------------------------
     Atomic transaction:
       1. Create GiftVoucherBooks doc
       2. Create N GiftVouchers docs
       3. Populate response vouchers on success
  ====================================================== */

  const generateVouchers = async () => {
    if (!bookForm.groupId) return alert("Select Gift Voucher Group");
    if (!bookForm.bookCode) return alert("Enter Book Code");
    if (!bookForm.bookName) return alert("Enter Book Name");

    const noOfVouchers = Number(bookForm.noOfVouchers);
    if (!noOfVouchers || noOfVouchers <= 0) {
      return alert("Enter valid voucher quantity");
    }

    const startingNo = Number(bookForm.startingNo || 1);
    const serialLength = Number(bookForm.serialLength || 8);
    const voucherPrefix = bookForm.voucherPrefix.trim();
    const voucherValue = Number(bookForm.voucherValue || 0);
    const validityDays = Number(bookForm.validityDays || 0);

    try {
      setLoading(true);

      const generatedVouchers = await runFirestoreTransaction(async (tx) => {
        /* ---- 1. Book doc ---- */

        const bookRef = doc(collection(db, BOOKS));
        tx.set(bookRef, {
          GroupID: bookForm.groupId,
          BookCode: bookForm.bookCode.trim(),
          BookName: bookForm.bookName.trim(),
          VoucherType: voucherType,
          StartingNo: startingNo,
          SerialLength: serialLength,
          NoOfVouchers: noOfVouchers,
          VoucherPrefix: voucherPrefix,
          VoucherValue: voucherValue,
          ValidityDays: validityDays,
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        /* ---- 2. Individual vouchers ---- */

        const created = [];

        for (let i = 0; i < noOfVouchers; i += 1) {
          const serialNum = startingNo + i;
          const serial = `${voucherPrefix}${pad(serialNum, serialLength)}`;
          const voucherNo = `${bookForm.bookCode.trim()}-${pad(serialNum, serialLength)}`;

          const expiryDate =
            validityDays > 0
              ? new Date(
                  Date.now() + validityDays * 24 * 60 * 60 * 1000
                ).toISOString()
              : null;

          const voucherRef = doc(collection(db, VOUCHERS));
          tx.set(voucherRef, {
            VoucherNo: voucherNo,
            VoucherSerial: serial,
            VoucherValue: voucherValue,
            VoucherType: voucherType,
            BookCode: bookForm.bookCode.trim(),
            BookName: bookForm.bookName.trim(),
            GroupID: bookForm.groupId,
            Status: "Available",
            ExpiryDate: expiryDate,
            LocationID: "",
            VoucherTemplateID: null,
            CreatedAt: serverTimestamp(),
            CreatedBy: username,
            IsDelete: 0,
          });

          created.push({
            GiftVoucherID: voucherRef.id,
            VoucherNo: voucherNo,
            VoucherSerial: serial,
            VoucherValue: voucherValue,
            VoucherType: voucherType,
            BookCode: bookForm.bookCode.trim(),
            BookName: bookForm.bookName.trim(),
            Status: "Available",
            ExpiryDate: expiryDate,
            LocationID: "",
          });
        }

        return created;
      });

      setVouchers(generatedVouchers);
      alert(`Generated ${generatedVouchers.length} vouchers successfully.`);

      setActiveTab("master");
    } catch (err) {
      console.error("GENERATE VOUCHERS ERROR:", err);
      alert(err.message || "Voucher generation failed");
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     SELECTION
  ====================================================== */

  const toggleVoucher = (id) => {
    setSelectedVouchers((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  };

  const selectAllVouchers = () => {
    const available = vouchers.filter((v) => v.Status === "Available");

    if (selectedVouchers.length === available.length) {
      setSelectedVouchers([]);
    } else {
      setSelectedVouchers(available.map((v) => v.GiftVoucherID));
    }
  };

  /* ======================================================
     TRANSFER VOUCHERS
     ------------------------------------------------------
     Atomic transaction:
       1. Create GiftVoucherTransfers doc
       2. Update each selected voucher:
          - Status: "Transferred"
          - LocationID: toLocationId
  ====================================================== */

  const transferVouchers = async () => {
    if (selectedVouchers.length === 0) return alert("Select vouchers first");
    if (!transfer.toLocationId) return alert("Select destination location");
    if (!transfer.documentNo)
      return alert("Generate or enter document number");

    const selectedVoucherData = vouchers.filter((v) =>
      selectedVouchers.includes(v.GiftVoucherID)
    );

    const invalid = selectedVoucherData.filter(
      (v) => v.Status !== "Available"
    );
    if (invalid.length > 0) {
      alert(
        `Cannot transfer ${invalid.length} voucher(s) as they are not in "Available" status.`
      );
      return;
    }

    try {
      setLoading(true);

      const totalValue = selectedVoucherData.reduce(
        (sum, v) => sum + Number(v.VoucherValue || 0),
        0
      );

      await runFirestoreTransaction(async (tx) => {
        /* ---- 1. Transfer record ---- */

        const transferRef = doc(collection(db, TRANSFERS));
        tx.set(transferRef, {
          DocumentNo: transfer.documentNo.trim(),
          VoucherType: voucherType,
          FromLocationID: selectedVoucherData[0]?.LocationID || "",
          ToLocationID: transfer.toLocationId,
          Reference: transfer.reference.trim() || "",
          Remark: transfer.remark.trim() || "",
          VoucherCount: selectedVoucherData.length,
          TotalValue: totalValue,
          Vouchers: selectedVoucherData.map((v) => ({
            GiftVoucherID: v.GiftVoucherID,
            VoucherNo: v.VoucherNo,
            VoucherSerial: v.VoucherSerial,
            VoucherValue: v.VoucherValue,
          })),
          TransferDate: new Date().toISOString(),
          CreatedAt: serverTimestamp(),
          CreatedBy: username,
          IsDelete: 0,
        });

        /* ---- 2. Update each voucher ---- */

        selectedVoucherData.forEach((v) => {
          const voucherRef = doc(db, VOUCHERS, v.GiftVoucherID);
          tx.update(voucherRef, {
            Status: "Transferred",
            LocationID: transfer.toLocationId,
            LastTransferDocumentNo: transfer.documentNo.trim(),
            LastTransferredAt: new Date().toISOString(),
            ModifiedAt: serverTimestamp(),
            ModifiedBy: username,
          });
        });
      });

      alert("Voucher transfer completed successfully");

      setSelectedVouchers([]);
      setTransfer({
        documentNo: "",
        toLocationId: "",
        reference: "",
        remark: "",
      });

      await loadVouchers();
      await loadTransferHistory();
    } catch (err) {
      console.error("TRANSFER VOUCHERS ERROR:", err);
      alert(err.message || "Transfer failed");
    } finally {
      setLoading(false);
    }
  };

  /* ======================================================
     EXPORT CSV / TXT
  ====================================================== */

  const exportProducts = (format) => {
    if (!vouchers || vouchers.length === 0) {
      alert("No vouchers available to export");
      return;
    }

    const rows = [
      ["VoucherSerial", "Price"],
      ...vouchers.map((v) => [v.VoucherSerial ?? "", v.VoucherValue ?? ""]),
    ];

    const content = rows
      .map((row) =>
        row
          .map((value) => {
            const s = String(value ?? "");
            if (
              s.includes(",") ||
              s.includes('"') ||
              s.includes("\n") ||
              s.includes("\r")
            ) {
              return `"${s.replace(/"/g, '""')}"`;
            }
            return s;
          })
          .join(",")
      )
      .join("\r\n");

    const extension = format === "csv" ? "csv" : "txt";
    const mimeType =
      format === "csv"
        ? "text/csv;charset=utf-8;"
        : "text/plain;charset=utf-8;";

    const blob = new Blob(["\uFEFF" + content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Voucher_Export_${new Date()
      .toISOString()
      .slice(0, 10)}.${extension}`;
    link.click();
    URL.revokeObjectURL(url);
  };

  /* ======================================================
     VOUCHER TEMPLATE RENDERING + PRINT
  ====================================================== */

  const renderVoucherTemplate = (layout, voucher) => {
    const page = layout?.page || {};
    const width = page.width || 100;
    const height = page.height || 60;
    const unit = page.unit || "mm";

    const elements = Array.isArray(layout?.elements) ? layout.elements : [];

    const replaceValue = (value) => {
      if (value === null || value === undefined) return "";
      return String(value)
        .replace(/\{VoucherNo\}/g, voucher.VoucherNo ?? "")
        .replace(/\{VoucherSerial\}/g, voucher.VoucherSerial ?? "")
        .replace(
          /\{VoucherValue\}/g,
          voucher.VoucherValue ?? voucher.Price ?? ""
        )
        .replace(/\{VoucherType\}/g, voucher.VoucherType ?? "")
        .replace(/\{ExpiryDate\}/g, voucher.ExpiryDate ?? "")
        .replace(/\{Status\}/g, voucher.Status ?? "");
    };

    const escapeHtml = (value) =>
      String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");

    const renderedElements = elements
      .filter((el) => el.visible !== false)
      .map((el) => {
        const x = el.x || 0;
        const y = el.y || 0;
        const w = el.width || 20;
        const h = el.height || 10;

        if (el.type === "barcode") {
          const barcodeValue = replaceValue(el.text);
          return `
            <div
              class="voucher-element voucher-barcode"
              data-barcode="${escapeHtml(barcodeValue)}"
              style="left:${x}${unit};top:${y}${unit};width:${w}${unit};height:${h}${unit};"
            >
              <svg class="barcode-svg" width="100%" height="100%"></svg>
            </div>
          `;
        }

        const text = replaceValue(el.text);
        return `
          <div
            class="voucher-element"
            style="
              left:${x}${unit};
              top:${y}${unit};
              width:${w}${unit};
              height:${h}${unit};
              font-size:${el.fontSize || 10}pt;
              font-weight:${el.bold ? "700" : "400"};
              text-align:${el.align || "left"};
            "
          >
            ${escapeHtml(text)}
          </div>
        `;
      })
      .join("");

    return `
      <div class="voucher-page" style="width:${width}${unit};height:${height}${unit};">
        ${renderedElements}
      </div>
    `;
  };

  const printVoucher = async (voucher) => {
    try {
      if (!voucher) return alert("Voucher information not available");

      const templateId = voucher.VoucherTemplateID || 1;

      /* ---- 1. Load template ---- */

      const template =
        (await getDocById(COLLECTIONS.VOUCHER_TEMPLATES, String(templateId))) ||
        (await getDocById(COLLECTIONS.VOUCHER_TEMPLATES, "1"));

      if (!template) {
        alert("Voucher template not found.");
        return;
      }

      const layout =
        template.layout ||
        (typeof template.LayoutJson === "string"
          ? JSON.parse(template.LayoutJson)
          : template.LayoutJson);

      if (!layout || !Array.isArray(layout.elements)) {
        alert("Voucher template layout is empty or invalid.");
        return;
      }

      /* ---- 2. Render + print ---- */

      const voucherHtml = renderVoucherTemplate(layout, voucher);

      const popup = window.open("", "_blank", "width=900,height=800");
      if (!popup) {
        alert("Please allow popups to print the voucher.");
        return;
      }

      popup.document.open();
      popup.document.write(`
        <!DOCTYPE html>
        <html>
          <head>
            <meta charset="UTF-8">
            <title>Gift Voucher ${voucher.VoucherNo || voucher.VoucherSerial || ""}</title>
            <style>
              @page {
                size: ${layout.page?.width || 100}mm ${layout.page?.height || 60}mm;
                margin: 0;
              }
              html, body { margin: 0; padding: 0; background: white; }
              body { font-family: Arial, Helvetica, sans-serif; }
              .voucher-page { position: relative; overflow: hidden; background: white; }
              .voucher-element {
                position: absolute;
                box-sizing: border-box;
                overflow: hidden;
                white-space: normal;
                line-height: 1.1;
              }
              .voucher-barcode { display: flex; align-items: center; justify-content: center; }
              .barcode-svg { width: 100%; height: 100%; }
              @media print { html, body { margin: 0; padding: 0; } }
            </style>
          </head>
          <body>
            ${voucherHtml}
            <script>
              window.onload = function () {
                const barcodes = document.querySelectorAll(".voucher-barcode");
                barcodes.forEach(function (item) {
                  const value = item.getAttribute("data-barcode");
                  const svg = item.querySelector(".barcode-svg");
                  if (value && svg && window.JsBarcode) {
                    try {
                      window.JsBarcode(svg, value, {
                        format: "CODE128", displayValue: true, margin: 0, width: 1.5, height: 30,
                      });
                    } catch (e) { console.error("Barcode error:", e); }
                  }
                });
                setTimeout(function () { window.print(); }, 500);
              };
            </script>
            <script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script>
          </body>
        </html>
      `);
      popup.document.close();
    } catch (err) {
      console.error("PRINT VOUCHER ERROR:", err);
      alert(err.message || "Unable to load voucher template");
    }
  };

  /* ======================================================
     HELPERS
  ====================================================== */

  const generateDocumentNo = () => {
    const now = new Date();
    const value =
      "TGV" +
      now.getFullYear() +
      pad(now.getMonth() + 1, 2) +
      pad(now.getDate(), 2) +
      pad(now.getHours(), 2) +
      pad(now.getMinutes(), 2) +
      pad(now.getSeconds(), 2);

    setTransfer({ ...transfer, documentNo: value });
  };

  const getSelectedVoucherDetails = () =>
    vouchers.filter((v) => selectedVouchers.includes(v.GiftVoucherID));

  const getLocationName = (locationId) => {
    if (!locationId) return "-";
    const loc = locations.find((l) => l.LocationID === locationId);
    return loc
      ? `${loc.LocationCode || ""} - ${loc.LocationName}`.trim()
      : String(locationId);
  };

  /* ======================================================
     RENDER
  ====================================================== */

  return (
    <div className="min-h-screen bg-gray-100 p-5">
      {/* HEADER */}
      <div className="bg-white rounded-xl shadow p-5 mb-5">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">
              Gift Voucher Management
            </h1>
            <p className="text-gray-500 mt-1">
              Gift Voucher / Coupon Management System
            </p>
          </div>

          <div className="flex gap-2">
            <button
              onClick={() => setVoucherType("Voucher")}
              className={`px-5 py-2 rounded-lg font-semibold transition-colors ${
                voucherType === "Voucher"
                  ? "bg-orange-500 text-white"
                  : "bg-gray-100 hover:bg-gray-200"
              }`}
            >
              <Ticket size={18} className="inline mr-2" />
              Voucher
            </button>

            <button
              onClick={() => setVoucherType("Coupon")}
              className={`px-5 py-2 rounded-lg font-semibold transition-colors ${
                voucherType === "Coupon"
                  ? "bg-orange-500 text-white"
                  : "bg-gray-100 hover:bg-gray-200"
              }`}
            >
              <Gift size={18} className="inline mr-2" />
              Coupon
            </button>
          </div>
        </div>
      </div>

      {/* TABS */}
      <div className="bg-white rounded-xl shadow mb-5">
        <div className="flex border-b overflow-x-auto">
          <TabButton
            active={activeTab === "generation"}
            onClick={() => setActiveTab("generation")}
            icon={<Barcode size={18} />}
            text="Book Code Generation"
          />
          <TabButton
            active={activeTab === "master"}
            onClick={() => setActiveTab("master")}
            icon={<Gift size={18} />}
            text="Gift Voucher Master"
          />
          <TabButton
            active={activeTab === "barcode"}
            onClick={() => setActiveTab("barcode")}
            icon={<Barcode size={18} />}
            text="Gift Voucher Barcode"
          />
          <TabButton
            active={activeTab === "transfer"}
            onClick={() => setActiveTab("transfer")}
            icon={<ArrowRightLeft size={18} />}
            text="Voucher Transfer"
          />
        </div>
      </div>

      {/* ==================== BOOK GENERATION ==================== */}
      {activeTab === "generation" && (
        <div className="bg-white rounded-xl shadow p-6">
          <h2 className="text-xl font-bold mb-5">
            Gift Voucher Book Code Generation
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <Input
              label="Gift Voucher Group *"
              name="groupCode"
              value={groupForm.groupCode}
              onChange={handleGroupChange}
              placeholder="Enter group code"
            />
            <Input
              label="Group Name *"
              name="groupName"
              value={groupForm.groupName}
              onChange={handleGroupChange}
              placeholder="Enter group name"
            />

            <div>
              <label className="block font-medium mb-2">Based On</label>
              <select
                name="basedOn"
                value={groupForm.basedOn}
                onChange={handleGroupChange}
                className="w-full border rounded-lg px-3 py-3"
              >
                <option>Book Serial</option>
                <option>Voucher Serial</option>
              </select>
            </div>

            <Input
              label="Gift Voucher Value"
              name="voucherValue"
              type="number"
              value={groupForm.voucherValue}
              onChange={handleGroupChange}
            />
            <Input
              label="Validity Period (Days)"
              name="validityDays"
              type="number"
              value={groupForm.validityDays}
              onChange={handleGroupChange}
            />
            <Input
              label="Percentage of Coupon (%)"
              name="percentageOfCoupon"
              type="number"
              value={groupForm.percentageOfCoupon}
              onChange={handleGroupChange}
            />
          </div>

          <div className="mt-6 flex justify-end gap-3">
            <button
              onClick={() =>
                setGroupForm({
                  groupCode: "",
                  groupName: "",
                  basedOn: "Book Serial",
                  voucherValue: "",
                  validityDays: "",
                  percentageOfCoupon: "",
                })
              }
              className="px-5 py-3 rounded-lg border hover:bg-gray-50"
            >
              Clear
            </button>
            <button
              onClick={saveGroup}
              disabled={loading}
              className="bg-orange-500 text-white px-6 py-3 rounded-lg font-semibold hover:bg-orange-600 disabled:opacity-50"
            >
              Save Group
            </button>
          </div>

          <hr className="my-8" />

          <h2 className="text-xl font-bold mb-5">Generate Voucher Book</h2>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <label className="block font-medium mb-2">
                Gift Voucher Group *
              </label>
              <select
                name="groupId"
                value={bookForm.groupId}
                onChange={handleBookChange}
                className="w-full border rounded-lg px-3 py-3"
              >
                <option value="">Select Group</option>
                {groups.map((g) => (
                  <option key={g.GiftVoucherGroupID} value={g.GiftVoucherGroupID}>
                    {g.GroupCode} - {g.GroupName}
                  </option>
                ))}
              </select>
            </div>

            <Input
              label="Book Code *"
              name="bookCode"
              value={bookForm.bookCode}
              onChange={handleBookChange}
              placeholder="Enter book code"
            />
            <Input
              label="Book Name *"
              name="bookName"
              value={bookForm.bookName}
              onChange={handleBookChange}
              placeholder="Enter book name"
            />
            <Input
              label="Starting No *"
              name="startingNo"
              type="number"
              value={bookForm.startingNo}
              onChange={handleBookChange}
            />
            <Input
              label="Serial Length *"
              name="serialLength"
              type="number"
              value={bookForm.serialLength}
              onChange={handleBookChange}
            />
            <Input
              label="No of Vouchers on Book *"
              name="noOfVouchers"
              type="number"
              value={bookForm.noOfVouchers}
              onChange={handleBookChange}
            />
            <Input
              label="Voucher Prefix"
              name="voucherPrefix"
              value={bookForm.voucherPrefix}
              onChange={handleBookChange}
              placeholder="Optional prefix"
            />
            <Input
              label="Gift Voucher Value"
              name="voucherValue"
              type="number"
              value={bookForm.voucherValue}
              onChange={handleBookChange}
              placeholder="Override group value"
            />
            <Input
              label="Validity Period (Days)"
              name="validityDays"
              type="number"
              value={bookForm.validityDays}
              onChange={handleBookChange}
              placeholder="Override group validity"
            />
          </div>

          <div className="mt-6 flex justify-end">
            <button
              onClick={generateVouchers}
              disabled={loading}
              className="bg-orange-500 hover:bg-orange-600 text-white px-7 py-3 rounded-lg font-bold disabled:opacity-50"
            >
              <Plus size={18} className="inline mr-2" />
              Generate Vouchers
            </button>
          </div>
        </div>
      )}

      {/* ==================== MASTER ==================== */}
      {activeTab === "master" && (
        <VoucherTable
          vouchers={vouchers}
          selectedVouchers={selectedVouchers}
          toggleVoucher={toggleVoucher}
          printVoucher={printVoucher}
          loadVouchers={loadVouchers}
          search={search}
          setSearch={setSearch}
          loading={loading}
          showSelect={true}
          exportProducts={exportProducts}
        />
      )}

      {/* ==================== BARCODE ==================== */}
      {activeTab === "barcode" && (
        <div className="bg-white rounded-xl shadow p-6">
          <h2 className="text-xl font-bold mb-5">Gift Voucher Barcode</h2>

          <div className="grid md:grid-cols-3 gap-4 mb-5">
            <Input
              label="Voucher No"
              value={search.voucherNo}
              onChange={(e) =>
                setSearch({ ...search, voucherNo: e.target.value })
              }
            />
            <Input
              label="Voucher Serial"
              value={search.serial}
              onChange={(e) =>
                setSearch({ ...search, serial: e.target.value })
              }
            />
            <div className="flex items-end">
              <button
                onClick={loadVouchers}
                className="w-full bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700"
              >
                <Search size={18} className="inline mr-2" />
                Load Data
              </button>
            </div>
          </div>

          <VoucherTable
            vouchers={vouchers}
            selectedVouchers={[]}
            toggleVoucher={() => {}}
            printVoucher={printVoucher}
            loadVouchers={loadVouchers}
            search={search}
            setSearch={setSearch}
            loading={loading}
            showSelect={false}
            exportProducts={exportProducts}
          />
        </div>
      )}

      {/* ==================== TRANSFER ==================== */}
      {activeTab === "transfer" && (
        <div className="bg-white rounded-xl shadow p-6">
          <div className="flex justify-between items-center mb-5">
            <h2 className="text-xl font-bold">Gift Voucher Transfer</h2>

            <div className="flex gap-2">
              <button
                onClick={generateDocumentNo}
                className="px-4 py-2 bg-gray-100 rounded-lg hover:bg-gray-200"
              >
                Generate Document No
              </button>
              <button
                onClick={() => {
                  setShowHistory(!showHistory);
                  if (!showHistory) loadTransferHistory();
                  setShowTransferDetails(false);
                }}
                className="px-4 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200"
              >
                <History size={18} className="inline mr-1" />
                {showHistory ? "Hide History" : "View History"}
              </button>
              <button
                onClick={loadLocations}
                disabled={locationsLoading}
                className="px-4 py-2 bg-green-100 text-green-700 rounded-lg hover:bg-green-200"
              >
                <RefreshCw
                  size={18}
                  className={`inline mr-1 ${locationsLoading ? "animate-spin" : ""}`}
                />
                Refresh Locations
              </button>
            </div>
          </div>

          {/* Transfer history */}
          {showHistory && (
            <div className="mb-5 p-4 bg-gray-50 rounded-lg max-h-80 overflow-y-auto">
              <h3 className="font-semibold mb-3 flex justify-between items-center">
                <span>Transfer History</span>
                <button
                  onClick={() => {
                    setShowTransferDetails(false);
                    loadTransferHistory();
                  }}
                  className="text-sm text-blue-600 hover:text-blue-800"
                >
                  <RefreshCw size={14} className="inline" /> Refresh
                </button>
              </h3>

              {transferHistory.length === 0 ? (
                <p className="text-gray-500 text-sm">No transfer history found</p>
              ) : (
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left bg-gray-200">
                      <th className="p-2">Document No</th>
                      <th className="p-2">To Location</th>
                      <th className="p-2">Vouchers</th>
                      <th className="p-2">Total Value</th>
                      <th className="p-2">Transfer Date</th>
                      <th className="p-2"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {transferHistory.map((h) => (
                      <tr key={h.GiftVoucherTransferID} className="border-b hover:bg-gray-100">
                        <td className="p-2 font-semibold">{h.DocumentNo || "-"}</td>
                        <td className="p-2">{getLocationName(h.ToLocation)}</td>
                        <td className="p-2 text-center">{h.VoucherCount}</td>
                        <td className="p-2 text-right">
                          Rs. {Number(h.TotalValue || 0).toFixed(2)}
                        </td>
                        <td className="p-2">
                          {h.TransferDate
                            ? new Date(h.TransferDate).toLocaleString()
                            : "-"}
                        </td>
                        <td className="p-2">
                          <button
                            onClick={() =>
                              loadTransferDetails(h.GiftVoucherTransferID)
                            }
                            className="text-blue-600 hover:text-blue-800 text-sm"
                          >
                            Details
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}

              {showTransferDetails && transferDetails.length > 0 && (
                <div className="mt-4 p-4 bg-white rounded-lg border border-gray-200">
                  <div className="flex justify-between items-center mb-3">
                    <h4 className="font-semibold text-gray-700">
                      Transfer Details
                    </h4>
                    <button
                      onClick={() => setShowTransferDetails(false)}
                      className="text-gray-500 hover:text-gray-700"
                    >
                      <X size={18} />
                    </button>
                  </div>

                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-left bg-gray-100">
                        <th className="p-2">Voucher No</th>
                        <th className="p-2">Serial</th>
                        <th className="p-2">Value</th>
                      </tr>
                    </thead>
                    <tbody>
                      {transferDetails.map((d, i) => (
                        <tr key={i} className="border-b">
                          <td className="p-2 font-semibold">{d.VoucherNo}</td>
                          <td className="p-2">{d.VoucherSerial}</td>
                          <td className="p-2">
                            Rs. {Number(d.VoucherValue || 0).toFixed(2)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="font-bold">
                        <td colSpan="2" className="p-2 text-right">
                          Total:
                        </td>
                        <td className="p-2">
                          Rs.{" "}
                          {transferDetails
                            .reduce(
                              (s, d) => s + Number(d.VoucherValue || 0),
                              0
                            )
                            .toFixed(2)}
                        </td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </div>
          )}

          <div className="grid md:grid-cols-3 gap-5">
            <Input
              label="Document No *"
              value={transfer.documentNo}
              onChange={(e) =>
                setTransfer({ ...transfer, documentNo: e.target.value })
              }
              placeholder="Enter document number"
            />

            <div>
              <label className="block font-medium mb-2">To Location *</label>
              <select
                value={transfer.toLocationId}
                onChange={(e) =>
                  setTransfer({ ...transfer, toLocationId: e.target.value })
                }
                className="w-full border border-gray-300 rounded-lg px-3 py-3 outline-none focus:ring-2 focus:ring-orange-400"
                disabled={locationsLoading}
              >
                <option value="">
                  {locationsLoading ? "Loading locations..." : "Select Location"}
                </option>
                {locations.map((l) => (
                  <option key={l.LocationID} value={l.LocationID}>
                    {l.LocationCode} - {l.LocationName}
                  </option>
                ))}
              </select>

              {locations.length === 0 && !locationsLoading && (
                <p className="text-red-500 text-sm mt-1">
                  No locations available. Please refresh locations.
                </p>
              )}
            </div>

            <Input
              label="Reference"
              value={transfer.reference}
              onChange={(e) =>
                setTransfer({ ...transfer, reference: e.target.value })
              }
              placeholder="Enter reference number"
            />

            <Input
              label="Remark"
              value={transfer.remark}
              onChange={(e) =>
                setTransfer({ ...transfer, remark: e.target.value })
              }
              placeholder="Enter remarks"
            />
          </div>

          {/* Selected Vouchers Summary */}
          {selectedVouchers.length > 0 && (
            <div className="mt-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
              <div className="flex justify-between items-center">
                <h4 className="font-semibold text-blue-800">
                  Selected Vouchers ({selectedVouchers.length})
                </h4>
                <button
                  onClick={() => setSelectedVouchers([])}
                  className="text-red-500 text-sm hover:text-red-700"
                >
                  Clear All
                </button>
              </div>

              <div className="flex flex-wrap gap-2 mt-2">
                {getSelectedVoucherDetails().map((v) => (
                  <span
                    key={v.GiftVoucherID}
                    className="bg-blue-100 text-blue-800 px-3 py-1 rounded-full text-sm flex items-center gap-2"
                  >
                    {v.VoucherNo}
                    <button
                      onClick={() => toggleVoucher(v.GiftVoucherID)}
                      className="text-red-500 hover:text-red-700"
                    >
                      <X size={14} />
                    </button>
                  </span>
                ))}
              </div>

              {getSelectedVoucherDetails().length > 0 && (
                <div className="mt-3 text-sm text-gray-600">
                  Total Value: Rs.{" "}
                  {getSelectedVoucherDetails()
                    .reduce((s, v) => s + Number(v.VoucherValue || 0), 0)
                    .toFixed(2)}
                </div>
              )}
            </div>
          )}

          <div className="mt-6">
            <div className="flex justify-between items-center mb-3">
              <h3 className="font-bold">Available Vouchers</h3>
              <button
                onClick={selectAllVouchers}
                className="text-sm text-blue-600 hover:text-blue-800"
              >
                {selectedVouchers.length ===
                  vouchers.filter((v) => v.Status === "Available").length &&
                vouchers.length > 0
                  ? "Deselect All"
                  : "Select All"}
              </button>
            </div>

            <VoucherTable
              vouchers={vouchers}
              selectedVouchers={selectedVouchers}
              toggleVoucher={toggleVoucher}
              printVoucher={printVoucher}
              loadVouchers={loadVouchers}
              search={search}
              setSearch={setSearch}
              loading={loading}
              showSelect={true}
              exportProducts={exportProducts}
            />
          </div>

          <div className="mt-5 flex justify-end gap-3">
            <button
              onClick={() => {
                setSelectedVouchers([]);
                setTransfer({
                  documentNo: "",
                  toLocationId: "",
                  reference: "",
                  remark: "",
                });
              }}
              className="border px-5 py-3 rounded-lg hover:bg-gray-50"
            >
              Clear All
            </button>
            <button
              onClick={transferVouchers}
              disabled={
                loading ||
                selectedVouchers.length === 0 ||
                !transfer.toLocationId ||
                !transfer.documentNo
              }
              className="bg-orange-500 text-white px-7 py-3 rounded-lg font-bold disabled:opacity-50 disabled:cursor-not-allowed hover:bg-orange-600"
            >
              <ArrowRightLeft size={18} className="inline mr-2" />
              Transfer Selected ({selectedVouchers.length})
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ======================================================
   TAB BUTTON
====================================================== */

function TabButton({ active, onClick, icon, text }) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-2 px-5 py-4 whitespace-nowrap font-semibold border-b-2 transition-colors ${
        active
          ? "border-orange-500 text-orange-500"
          : "border-transparent text-gray-600 hover:text-gray-800 hover:border-gray-300"
      }`}
    >
      {icon}
      {text}
    </button>
  );
}

/* ======================================================
   INPUT
====================================================== */

function Input({
  label,
  name,
  value,
  onChange,
  type = "text",
  placeholder = "",
}) {
  return (
    <div>
      <label className="block font-medium mb-2">{label}</label>
      <input
        name={name}
        type={type}
        value={value}
        onChange={onChange}
        placeholder={placeholder}
        className="w-full border border-gray-300 rounded-lg px-3 py-3 outline-none focus:ring-2 focus:ring-orange-400"
      />
    </div>
  );
}

/* ======================================================
   VOUCHER TABLE
====================================================== */

function VoucherTable({
  vouchers,
  selectedVouchers,
  toggleVoucher,
  printVoucher,
  loadVouchers,
  search,
  setSearch,
  loading,
  showSelect = true,
  exportProducts,
}) {
  return (
    <div className="bg-white rounded-xl shadow p-5">
      {/* Search + Export */}
      <div className="flex flex-wrap gap-3 mb-5">
        <input
          value={search.voucherNo}
          onChange={(e) => setSearch({ ...search, voucherNo: e.target.value })}
          placeholder="Search voucher no..."
          className="border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-orange-400"
        />

        <input
          value={search.serial}
          onChange={(e) => setSearch({ ...search, serial: e.target.value })}
          placeholder="Search serial..."
          className="border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-orange-400"
        />

        <button
          onClick={loadVouchers}
          className="bg-blue-600 text-white px-5 py-2 rounded-lg hover:bg-blue-700"
        >
          <Search size={17} className="inline mr-2" />
          Search
        </button>

        <button
          onClick={() => setSearch({ voucherNo: "", serial: "", status: "" })}
          className="border px-5 py-2 rounded-lg hover:bg-gray-50"
        >
          <RefreshCw size={17} className="inline mr-2" />
          Clear
        </button>

        <button
          onClick={() => exportProducts("csv")}
          disabled={!vouchers || vouchers.length === 0}
          className="bg-green-600 text-white px-5 py-2 rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Export CSV
        </button>

        <button
          onClick={() => exportProducts("txt")}
          disabled={!vouchers || vouchers.length === 0}
          className="bg-gray-700 text-white px-5 py-2 rounded-lg hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Export TXT
        </button>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-gray-100 text-left">
              {showSelect && <th className="p-3">Select</th>}
              <th className="p-3">Voucher No</th>
              <th className="p-3">Voucher Serial</th>
              <th className="p-3">Book</th>
              <th className="p-3">Value</th>
              <th className="p-3">Status</th>
              <th className="p-3">Expiry</th>
              <th className="p-3">Action</th>
            </tr>
          </thead>

          <tbody>
            {vouchers.length === 0 ? (
              <tr>
                <td
                  colSpan={showSelect ? "8" : "7"}
                  className="text-center p-8 text-gray-500"
                >
                  {loading ? "Loading..." : "No vouchers found"}
                </td>
              </tr>
            ) : (
              vouchers.map((v) => (
                <tr key={v.GiftVoucherID} className="border-b hover:bg-gray-50">
                  {showSelect && (
                    <td className="p-3">
                      <input
                        type="checkbox"
                        checked={selectedVouchers.includes(v.GiftVoucherID)}
                        onChange={() => toggleVoucher(v.GiftVoucherID)}
                        disabled={v.Status !== "Available"}
                        className="cursor-pointer"
                      />
                    </td>
                  )}

                  <td className="p-3 font-semibold">{v.VoucherNo}</td>

                  <td className="p-3">
                    <span className="font-mono font-semibold">
                      {v.VoucherSerial}
                    </span>
                  </td>

                  <td className="p-3">{v.BookCode}</td>

                  <td className="p-3 font-bold">
                    Rs. {Number(v.VoucherValue || 0).toFixed(2)}
                  </td>

                  <td className="p-3">
                    <span
                      className={`px-3 py-1 rounded-full text-xs font-semibold ${
                        v.Status === "Available"
                          ? "bg-green-100 text-green-700"
                          : v.Status === "Transferred"
                          ? "bg-blue-100 text-blue-700"
                          : v.Status === "Redeemed"
                          ? "bg-purple-100 text-purple-700"
                          : "bg-gray-100 text-gray-700"
                      }`}
                    >
                      {v.Status || "Unknown"}
                    </span>
                  </td>

                  <td className="p-3">
                    {v.ExpiryDate
                      ? new Date(v.ExpiryDate).toLocaleDateString()
                      : "-"}
                  </td>

                  <td className="p-3">
                    <button
                      onClick={() => printVoucher(v)}
                      className="bg-gray-800 text-white px-3 py-2 rounded-lg hover:bg-gray-700"
                      title="Print Voucher"
                    >
                      <Printer size={16} className="inline" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}