// src/firebase.js
import { initializeApp, getApps } from "firebase/app";
import {
  getAuth,
  setPersistence,
  browserLocalPersistence,
} from "firebase/auth";
import {
  getFirestore,
  initializeFirestore,
  persistentLocalCache,
  persistentMultipleTabManager,
} from "firebase/firestore";
import { getStorage } from "firebase/storage";

const firebaseConfig = {
  apiKey:            process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain:        process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId:         process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket:     process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId:             process.env.REACT_APP_FIREBASE_APP_ID,
};

// getApps().length === 0 means "first load of this tab".
// On CRA hot reload the module re-executes but the app already exists,
// so we must NOT re-call initializeFirestore() (it throws).
const isFirstInit = !getApps().length;
const app = isFirstInit ? initializeApp(firebaseConfig) : getApps()[0];

export const auth    = getAuth(app);
export const storage = getStorage(app);

// ---- Firestore with persistent (IndexedDB) cache ----
// First-ever load reads from network; every subsequent getDoc/getDocs
// is served from IndexedDB in ~1–5 ms. This is what makes the
// profile fetch in AuthContext feel instant on reload/login.
export const db = isFirstInit
  ? initializeFirestore(app, {
      localCache: persistentLocalCache({
        // multi-tab because /customer-display often runs in a 2nd tab.
        // If you're strictly single-tab, swap for persistentSingleTabManager().
        tabManager: persistentMultipleTabManager(),
      }),
    })
  : getFirestore(app);

// Explicitly pin auth persistence to localStorage (Firebase's default on
// web, but this prevents a silent future regression to session-only).
if (isFirstInit) {
  setPersistence(auth, browserLocalPersistence).catch((e) =>
    console.warn("[auth] persistence not set:", e)
  );
}

export default app;