// ============================================================
// Loading splash — kept tiny so it never "hangs"
// ============================================================
function LoadingSession({ label = "Loading session…" }) {
  return (
    <div className="h-screen flex items-center justify-center bg-[#e0e5ec]">
      <div className="text-gray-600 text-lg font-medium">{label}</div>
    </div>
  );
}

// ============================================================
// LOGIN
// ============================================================
function Login() {
  const navigate = useNavigate();
  const { login, user, loading: authLoading } = useContext(AuthContext);

  const [form, setForm] = useState({ username: "", password: "" });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // If a session already exists (Firebase restores it on load, or the user
  // just signed in), skip the login form entirely.
  // NOTE: `user` is set by AuthContext the instant sign-in resolves — BEFORE
  // the Firestore profile loads — so navigation happens within ~200–600 ms
  // of pressing Login instead of waiting for Firestore too.
  useEffect(() => {
    if (!authLoading && user) navigate("/home", { replace: true });
  }, [user, authLoading, navigate]);

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    try {
      await login(form.username, form.password);
      // Navigation happens in the useEffect above once `user` is set.
    } catch (err) {
      console.error("LOGIN ERROR:", err);
      setError(
        err?.response?.data?.message ||
          err?.message ||
          "Unable to sign in. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-r from-blue-500 to-indigo-600 flex items-center justify-center">
      <div className="bg-white w-full max-w-md rounded-xl shadow-2xl p-8">
        <h2 className="text-3xl font-bold text-center text-gray-700">Login</h2>
        <p className="text-center text-gray-500 mt-2">Sign in to continue</p>

        {error && (
          <div className="bg-red-100 text-red-700 p-3 rounded mt-5">
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="mt-6">
          <div className="mb-5">
            <label className="block mb-2 font-medium">Username</label>
            <input
              type="text"
              name="username"
              value={form.username}
              onChange={handleChange}
              className="w-full border rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="Enter username"
              autoComplete="username"
              required
            />
          </div>

          <div className="mb-6">
            <label className="block mb-2 font-medium">Password</label>
            <input
              type="password"
              name="password"
              value={form.password}
              onChange={handleChange}
              className="w-full border rounded-lg px-4 py-3 focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="Enter password"
              autoComplete="current-password"
              required
            />
          </div>

          <button
            disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-lg font-semibold transition disabled:opacity-60"
          >
            {loading ? "Signing In..." : "Login"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ============================================================
// ROUTES (inside Router so useContext works)
// ============================================================
function AppRoutes() {
  const { user, loading } = useContext(AuthContext);

  // Wait only for the initial Firebase auth restore. This is typically
  // 50–200 ms on a hard refresh; on the Login page it fires once and
  // then we render the form.
  if (loading) return <LoadingSession />;

  // CashierID may briefly be undefined right after a first-ever login
  // (profile is being fetched in the background). PermissionsProvider
  // already receives `null` when logged out, so it must — and does —
  // handle a missing value without crashing.
  const cashierID =
    user?.CashierID ??
    user?.CashierId ??
    user?.cashierID ??
    user?.id ??
    null;

  return (
    <PermissionsProvider cashierID={cashierID}>
      <Routes>
        {/* public */}
        <Route path="/POS/" element={<Login />} />
        <Route path="/registration" element={<Register />} />

        {/* protected — everything below requires auth */}
        <Route element={<Protectedroute />}>
          <Route path="/home" element={<Homes />} />
          <Route path="/Dashboard" element={<Dashboard />} />
          <Route path="/Catalog" element={<Catalog />} />
          <Route path="/Settingss" element={<Settingss />} />
          <Route path="/sidebar" element={<Sidebar />} />
          <Route path="/ERP" element={<ERP />} />

          <Route path="/products" element={<CreateProduct />} />
          <Route path="/department" element={<Department />} />
          <Route path="/subcatagory" element={<Subcatagory />} />
          <Route path="/catagory" element={<Catagory />} />
          <Route path="/Salesperson" element={<Salesperson />} />
          <Route path="/supplier" element={<Supplier />} />
          <Route path="/customer" element={<Customer />} />

          <Route path="/Accounts" element={<Accounts />} />
          <Route path="/VoucherTemplate" element={<VoucherTemplate />} />
          <Route path="/print-checks" element={<PrintChecks />} />
          <Route path="/expenses" element={<ExpenseManagement />} />
          <Route path="/account-transfers" element={<AccountTransfer />} />
          <Route path="/cash-collection" element={<CashCollection />} />
          <Route path="/cash-on-hand" element={<CashOnHand />} />
          <Route
            path="/account-reconciliation"
            element={<AccountReconciliation />}
          />
          <Route path="/supplier-payment" element={<SupplierPayment />} />
          <Route path="/checkbooks" element={<CheckBooks />} />
          <Route path="/account-ledger" element={<AccountLedger />} />

          <Route path="/loyalty" element={<Loyalty />} />
          <Route path="/gift-voucher" element={<GiftVoucher />} />
          <Route path="/promotion" element={<Promotion />} />

          <Route path="/PosSetting" element={<PosSetting />} />
          <Route path="/product-price" element={<ProductPriceChange />} />
          <Route path="/BinCard" element={<BinCard />} />

          <Route path="/cashier-permission" element={<CashierPermission />} />
          <Route
            path="/product-management"
            element={<ProductManagement />}
          />
          <Route path="/check-reports" element={<CheckReports />} />
          <Route path="/check-template" element={<CheckTemplate />} />

          <Route path="/cashier" element={<Cashier />} />
          <Route path="/cashier-group" element={<Cashier_group />} />
          <Route path="/location" element={<Location />} />
          <Route path="/PO" element={<PO />} />
          <Route path="/GRN" element={<GRN />} />
          <Route path="/PRNote" element={<PRNote />} />
          <Route path="/SRNote" element={<SRNote />} />
          <Route path="/SORDER" element={<SORDER />} />
          <Route path="/Stadjust" element={<Stadjust />} />
          <Route path="/TOG" element={<TOG />} />
          <Route path="/Invoice" element={<Invoice />} />
          <Route path="/company" element={<Company />} />
          <Route path="/employee" element={<Employee />} />
          <Route path="/Reorder" element={<Reorder />} />

          <Route path="/customer-display" element={<CustomerDisplay />} />
          <Route path="/Stadjustapprove" element={<Stadj />} />

          <Route path="/Salesreport" element={<Salesreport />} />
          <Route path="/Salesregister" element={<Salesregister />} />
          <Route path="/Saleshistory" element={<Saleshistory />} />
          <Route path="/Logout" element={<Logout />} />
          <Route
            path="/account-transaction-logs"
            element={<AccountTransactionLogs />}
          />
        </Route>
      </Routes>
    </PermissionsProvider>
  );
}

// ============================================================
// APP
// ============================================================
export default function App() {
  return (
    <Router>
      <AppRoutes />
    </Router>
  );
}