// src/pos/SERVER/AuthContext.js
import React, {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  onAuthStateChanged,
  signInWithEmailAndPassword,
  signOut,
} from "firebase/auth";
import { doc, getDoc, getDocFromCache } from "firebase/firestore";
import { auth, db } from "../../firebase.js";

export const AuthContext = createContext(null);

const USERS_COLLECTION = "cashier"; // adjust to your collection
const PROFILE_TIMEOUT_MS = 8000;    // hard cap so a cold Firestore can't hang login

// ---- tiny localStorage cache for the profile doc ----
const cacheKey   = (uid) => `auth.profile.${uid}`;
const readCache  = (uid) => {
  try {
    const raw = localStorage.getItem(cacheKey(uid));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};
const writeCache = (uid, profile) => {
  try { localStorage.setItem(cacheKey(uid), JSON.stringify(profile)); } catch {}
};
const clearCache = (uid) => {
  try { localStorage.removeItem(cacheKey(uid)); } catch {}
};

const withTimeout = (promise, ms, label) =>
  Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`${label} timed out`)), ms)
    ),
  ]);

export function AuthProvider({ children }) {
  const [user, setUser]                     = useState(null);
  const [loading, setLoading]               = useState(true);   // auth restore
  const [profileLoading, setProfileLoading] = useState(false);  // profile hydration
  const [error, setError]                   = useState("");

  // Guards against duplicate profile fetches (React 18 StrictMode + token
  // refresh events can both fire onAuthStateChanged for the same uid).
  const inFlightFor = useRef(null);

  /* ---- Restore session / react to sign-in ---- */
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (fbUser) => {
      if (!fbUser) {
        inFlightFor.current = null;
        setUser(null);
        setProfileLoading(false);
        setLoading(false);
        return;
      }

      // 1) Unblock the app IMMEDIATELY from Auth alone.
      //    The Login screen's useEffect sees `user` and navigates.
      setUser({ uid: fbUser.uid, email: fbUser.email, profileReady: false });
      setLoading(false);

      // 2) Instant hydration from localStorage (0 network, ~1 ms).
      const cached = readCache(fbUser.uid);
      if (cached) {
        setUser({
          uid: fbUser.uid,
          email: fbUser.email,
          ...cached,
          profileReady: true,
        });
      }

      // 3) Refresh the profile in the background (never blocks login).
      if (inFlightFor.current === fbUser.uid) return;
      inFlightFor.current = fbUser.uid;
      setProfileLoading(true);

      try {
        const ref = doc(db, USERS_COLLECTION, fbUser.uid);

        // Prefer the IndexedDB cache (fast path once persistence is warm).
        let snap;
        try {
          snap = await getDocFromCache(ref);
        } catch {
          // Cache miss (first login, or persistence not warm) → network,
          // but capped so a slow Firestore can never hang the app.
          snap = await withTimeout(
            getDoc(ref),
            PROFILE_TIMEOUT_MS,
            "profile fetch"
          );
        }

        const profile = snap.exists() ? snap.data() : {};
        writeCache(fbUser.uid, profile);
        setUser({
          uid: fbUser.uid,
          email: fbUser.email,
          ...profile,
          profileReady: true,
        });
      } catch (e) {
        console.error("[Auth] profile fetch failed:", e);
        // Keep whatever we have (cache / bare auth) — just mark it ready
        // so consumers don't spin forever.
        setUser((prev) =>
          prev
            ? { ...prev, profileReady: true }
            : { uid: fbUser.uid, email: fbUser.email, profileReady: true }
        );
      } finally {
        setProfileLoading(false);
        inFlightFor.current = null;
      }
    });

    return unsub;
  }, []);

  /* ---- Email/password login ---- */
  const login = useCallback(async (email, password) => {
    setError("");
    try {
      const cred = await signInWithEmailAndPassword(auth, email, password);
      // NOTE: we do NOT await the profile here. `onAuthStateChanged`
      // takes over, sets `user`, and the Login component navigates.
      return cred.user;
    } catch (err) {
      const msg = friendly(err);
      setError(msg);
      throw new Error(msg);
    }
  }, []);

  const logout = useCallback(async () => {
    const uid = auth.currentUser?.uid;
    if (uid) clearCache(uid);
    await signOut(auth);
  }, []);

  const value = useMemo(
    () => ({ user, loading, profileLoading, error, login, logout, setError }),
    [user, loading, profileLoading, error, login, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

function friendly(err) {
  switch (err?.code) {
    case "auth/invalid-credential":
    case "auth/wrong-password":
    case "auth/user-not-found":
      return "Wrong email or password.";
    case "auth/invalid-email":
      return "That email address is not valid.";
    case "auth/user-disabled":
      return "This account has been disabled.";
    case "auth/too-many-requests":
      return "Too many attempts. Please try again in a minute.";
    case "auth/network-request-failed":
      return "Network problem. Check your connection.";
    case "auth/operation-not-allowed":
      return "Email/Password sign-in is disabled in Firebase Console.";
    case "auth/invalid-api-key":
    case "auth/api-key-not-valid":
      return "Firebase config is missing or wrong (check .env).";
    default:
      return err?.message || "Login failed.";
  }
}