// src/pos/Loyalty.jsx
// ============================================================
// Loyalty Management — React + Firestore
// ------------------------------------------------------------
// Reads:
//   • LoyaltySettings/main       (singleton — seeds via initializeFirestore)
//   • Category                   (master category list, for the Rate tab)
//   • LoyaltyCategories          (per-category earn rate)
//   • LoyaltyCustomers           (customer balances)
//   • LoyaltyTransactions        (ledger, last 500)
//
// Writes:
//   • LoyaltySettings/main       (Save Settings)
//   • LoyaltyCategories          (upsert by CategoryCode — Save / Toggle)
//   • LoyaltyCustomers           (add customer)
//
// Server-side (transitional — migrate to Cloud Functions later):
//   • POST /expire               (bulk point expiry)
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { doc, setDoc, serverTimestamp, query, orderBy, limit,collection } from "firebase/firestore";

import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import {
  
  listCollection,
  createDoc,
  updateDocById,
  readDoc,
} from "../lib/firestore";
import { db } from "../firebase";
import api from "../api";

/* =====================================================
   SMALL COMPONENTS (unchanged from the original)
===================================================== */
function Toggle({ checked, onChange, disabled = false }) {
  return (
    <button
      type="button"
      onClick={() => !disabled && onChange(!checked)}
      disabled={disabled}
      className={`relative h-6 w-11 shrink-0 rounded-full transition ${
        checked ? "bg-[#e99a00]" : "bg-gray-300"
      } ${disabled ? "opacity-50 cursor-not-allowed" : ""}`}
    >
      <span
        className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all ${
          checked ? "left-6" : "left-1"
        }`}
      />
    </button>
  );
}

function TabButton({ active, onClick, icon, children }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`flex items-center gap-2 rounded-xl px-5 py-2.5 text-sm font-medium transition ${
        active
          ? "bg-white text-gray-900 shadow-sm"
          : "text-gray-600 hover:bg-white/60 hover:text-gray-900"
      }`}
    >
      <span>{icon}</span>
      {children}
    </button>
  );
}

/* =====================================================
   MAIN LOYALTY COMPONENT
===================================================== */
export default function Loyalty() {
  const { user } = useContext(AuthContext);
  const { can, loading: permissionsLoading } = usePermissions();

  const canViewLoyalty = can("Loyalty", "View");
  const canAddLoyalty  = can("Loyalty", "Add");
  const canEditLoyalty = can("Loyalty", "Edit");

  const [activeTab, setActiveTab] = useState("configuration");

  const [settings, setSettings] = useState({
    pointsPerAmount:     100,
    amountPerPoint:      1,
    pointsExpiryDays:    365,
    minimumRedeemPoints: 0,
    otpRequired:         true,
    autoEnroll:          true,
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error,   setError]   = useState("");

  const availableTabs = useMemo(() => {
    if (!canViewLoyalty) return [];
    return ["configuration", "categories", "customers", "transactions"];
  }, [canViewLoyalty]);

  useEffect(() => {
    if (permissionsLoading) return;
    if (availableTabs.length === 0) return;
    if (!availableTabs.includes(activeTab)) setActiveTab(availableTabs[0]);
  }, [availableTabs, activeTab, permissionsLoading]);

  useEffect(() => {
    if (permissionsLoading || !canViewLoyalty) return;
    loadSettings();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewLoyalty]);

  /* -------- load settings (singleton) -------- */
  const loadSettings = async () => {
    try {
      setLoading(true);
      setError("");

      const data = await readDoc("LoyaltySettings", "main");
      if (!data) {
        // Shouldn't happen — initializeFirestore seeds it — but be safe
        setError("Loyalty settings have not been initialised. Run the setup script.");
        return;
      }

      setSettings({
        pointsPerAmount:     Number(data.PointsPerAmount     ?? 100),
        amountPerPoint:      Number(data.AmountPerPoint      ?? 1),
        pointsExpiryDays:    Number(data.PointsExpiryDays    ?? 365),
        minimumRedeemPoints: Number(data.MinimumRedeemPoints ?? 0),
        otpRequired:         Boolean(data.OTPRequired ?? true),
        autoEnroll:          Boolean(data.AutoEnroll  ?? true),
      });
    } catch (err) {
      console.error("LOAD SETTINGS:", err);
      setError(err?.message || "Unable to load loyalty settings");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setSettings((prev) => ({
      ...prev,
      [name]: value === "" ? "" : Number(value),
    }));
  };

  /* -------- save settings -------- */
  const handleSave = async () => {
    if (!canEditLoyalty) {
      setError("You do not have permission to modify loyalty settings.");
      return;
    }
    try {
      setLoading(true);
      setMessage("");
      setError("");

      await createDoc(
        "LoyaltySettings",
        {
          PointsPerAmount:     Number(settings.pointsPerAmount),
          AmountPerPoint:      Number(settings.amountPerPoint),
          PointsExpiryDays:    Number(settings.pointsExpiryDays),
          MinimumRedeemPoints: Number(settings.minimumRedeemPoints),
          OTPRequired:         Boolean(settings.otpRequired),
          AutoEnroll:          Boolean(settings.autoEnroll),
          UpdatedAt:           serverTimestamp(),
        },
        { customId: "main", username: user?.username }
      );

      setMessage("Loyalty settings saved successfully.");
    } catch (err) {
      console.error("SAVE SETTINGS:", err);
      setError(err?.message || "Failed to save settings");
    } finally {
      setLoading(false);
    }
  };

  /* -------- expire points (transitional server) -------- */
  const expirePoints = async () => {
    if (!canEditLoyalty) {
      setError("You do not have permission to run expiry.");
      return;
    }
    try {
      setLoading(true);
      setMessage("");
      setError("");

      const response = await api.post("/expire");
      const count = response?.data?.expiredCount ?? 0;
      setMessage(
        count === 0
          ? "No points to expire right now."
          : `${count} point batch${count === 1 ? "" : "es"} expired.`
      );
    } catch (err) {
      console.error("EXPIRE POINTS:", err);
      setError(
        err?.response?.data?.message || err?.message || "Failed to expire points"
      );
    } finally {
      setLoading(false);
    }
  };

  /* -------- derived example values -------- */
  const pointsRate = Number(settings.pointsPerAmount) || 1;
  const pointValue = Number(settings.amountPerPoint) || 0;
  const earnedPoints    = Math.floor(10000 / pointsRate);
  const redemptionValue = earnedPoints * pointValue;

  /* -------- access gate -------- */
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewLoyalty) {
    return (
      <div className="min-h-screen bg-white p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view the Loyalty module.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Loyalty</code>
          </p>
        </div>
      </div>
    );
  }

  /* -------- render -------- */
  return (
    <div className="min-h-screen bg-white text-gray-900">
      {/* HEADER */}
      <header className="flex flex-col gap-4 px-5 py-5 md:flex-row md:items-center md:justify-between">
        <div className="flex items-center gap-3">
          <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#fff1c9]">
            <svg
              className="h-6 w-6 text-[#e99a00]"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth="2"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z"
              />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-bold">Loyalty Points</h1>
            <p className="text-sm text-gray-500">
              Manage customer loyalty program
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {!canEditLoyalty && (
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}
          <span className="w-fit rounded-full bg-green-100 px-4 py-2 text-xs font-semibold text-green-700">
            Active
          </span>
        </div>
      </header>

      {/* TABS */}
      <div className="overflow-x-auto px-3">
        <div className="flex w-max rounded-xl bg-gray-100 p-1">
          {availableTabs.includes("configuration") && (
            <TabButton active={activeTab === "configuration"} onClick={() => setActiveTab("configuration")} icon="⚙">
              Configuration
            </TabButton>
          )}
          {availableTabs.includes("categories") && (
            <TabButton active={activeTab === "categories"} onClick={() => setActiveTab("categories")} icon="◇">
              Category Rates
            </TabButton>
          )}
          {availableTabs.includes("customers") && (
            <TabButton active={activeTab === "customers"} onClick={() => setActiveTab("customers")} icon="♧">
              Customers
            </TabButton>
          )}
          {availableTabs.includes("transactions") && (
            <TabButton active={activeTab === "transactions"} onClick={() => setActiveTab("transactions")} icon="◷">
              Transactions
            </TabButton>
          )}
        </div>
      </div>

      {/* BODY */}
      <main className="p-3">
        {activeTab === "configuration" && (
          <Configuration
            settings={settings}
            setSettings={setSettings}
            loading={loading}
            message={message}
            error={error}
            handleChange={handleChange}
            handleSave={handleSave}
            expirePoints={expirePoints}
            earnedPoints={earnedPoints}
            redemptionValue={redemptionValue}
            readOnly={!canEditLoyalty}
          />
        )}

        {activeTab === "categories" && (
          <CategoryRates username={user?.username} />
        )}

        {activeTab === "customers" && (
          <Customers canAdd={canAddLoyalty} username={user?.username} />
        )}

        {activeTab === "transactions" && <Transactions />}
      </main>
    </div>
  );
}

/* =====================================================
   CONFIGURATION (unchanged UI)
===================================================== */
function Configuration({
  settings, setSettings, loading, message, error,
  handleChange, handleSave, expirePoints,
  earnedPoints, redemptionValue, readOnly = false,
}) {
  return (
    <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
      <div className="border-b px-6 py-6">
        <h2 className="text-2xl font-semibold">Loyalty Configuration</h2>
        <p className="mt-1 text-sm text-gray-500">
          Configure customer loyalty points, redemption and expiry.
        </p>
      </div>

      {message && (
        <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
          {message}
        </div>
      )}
      {error && (
        <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}
      {readOnly && (
        <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
          Read-only mode — you cannot modify settings or run expiry.
        </div>
      )}

      <div className="grid grid-cols-1 gap-x-16 gap-y-8 px-6 py-8 md:grid-cols-2">
        <div>
          <label className="text-sm font-medium">Default Points Rate</label>
          <div className="mt-2 flex items-center gap-2">
            <span className="text-sm text-gray-500">1 point per Rs.</span>
            <input
              type="number" min="1" step="0.01" name="pointsPerAmount"
              value={settings.pointsPerAmount} onChange={handleChange}
              disabled={readOnly}
              className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
            />
          </div>
          <p className="mt-2 text-xs text-gray-500">
            Example: 200 means 1 point for every Rs.200 spent.
          </p>
        </div>

        <div>
          <label className="text-sm font-medium">Point Redemption Value</label>
          <div className="mt-2 flex items-center gap-2">
            <span className="text-sm text-gray-500">1 point = Rs.</span>
            <input
              type="number" min="0.01" step="0.01" name="amountPerPoint"
              value={settings.amountPerPoint} onChange={handleChange}
              disabled={readOnly}
              className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
            />
          </div>
        </div>

        <div>
          <label className="text-sm font-medium">Minimum Points to Redeem</label>
          <input
            type="number" min="0" step="1" name="minimumRedeemPoints"
            value={settings.minimumRedeemPoints} onChange={handleChange}
            disabled={readOnly}
            className="mt-3 w-32 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
          />
        </div>

        <div>
          <label className="text-sm font-medium">Points Expiry Period</label>
          <div className="mt-2 flex items-center gap-2">
            <input
              type="number" min="1" step="1" name="pointsExpiryDays"
              value={settings.pointsExpiryDays} onChange={handleChange}
              disabled={readOnly}
              className="w-28 rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
            />
            <span className="text-sm text-gray-500">days</span>
          </div>
        </div>

        <div className="flex items-start gap-4">
          <Toggle
            checked={settings.otpRequired} disabled={readOnly}
            onChange={(value) => setSettings((prev) => ({ ...prev, otpRequired: value }))}
          />
          <div>
            <h3 className="text-sm font-medium">Require OTP for Redemption</h3>
            <p className="mt-1 text-xs text-gray-500">
              Send OTP to customer and admin for verification.
            </p>
          </div>
        </div>

        <div className="flex items-start gap-4">
          <Toggle
            checked={settings.autoEnroll} disabled={readOnly}
            onChange={(value) => setSettings((prev) => ({ ...prev, autoEnroll: value }))}
          />
          <div>
            <h3 className="text-sm font-medium">Auto-enroll Retail Customers</h3>
            <p className="mt-1 text-xs text-gray-500">
              Automatically enroll retail customers in the loyalty program.
            </p>
          </div>
        </div>
      </div>

      <div className="mx-6 mb-6 rounded-xl border bg-gray-50 p-5">
        <h3 className="mb-4 font-semibold">Example</h3>
        <div className="grid gap-3 text-sm md:grid-cols-4">
          <div>
            <span className="text-gray-500">Sale</span>
            <div className="mt-1 font-semibold">Rs.10,000</div>
          </div>
          <div>
            <span className="text-gray-500">Points</span>
            <div className="mt-1 font-semibold">{earnedPoints}</div>
          </div>
          <div>
            <span className="text-gray-500">Expiry</span>
            <div className="mt-1 font-semibold">{settings.pointsExpiryDays} days</div>
          </div>
          <div>
            <span className="text-gray-500">Value</span>
            <div className="mt-1 font-semibold">Rs.{Number(redemptionValue).toFixed(2)}</div>
          </div>
        </div>
      </div>

      {!readOnly && (
        <div className="flex flex-col gap-3 border-t border-gray-200 px-6 py-5 sm:flex-row sm:justify-end">
          <button
            type="button" onClick={expirePoints} disabled={loading}
            className="rounded-xl border border-[#e99a00] px-5 py-3 text-sm font-semibold text-[#e99a00] transition hover:bg-[#fff7e6] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? "Processing…" : "Expire Points Now"}
          </button>
          <button
            type="button" onClick={handleSave} disabled={loading}
            className="rounded-xl bg-[#e99a00] px-6 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-[#d88d00] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? "Saving…" : "Save Settings"}
          </button>
        </div>
      )}
    </section>
  );
}

/* =====================================================
   CATEGORY RATES — upsert by CategoryCode
===================================================== */
function CategoryRates({ username }) {
  const { can } = usePermissions();
  const canEditLoyalty = can("Loyalty", "Edit");

  const [categories, setCategories] = useState([]);  // merged master + rate rows
  const [loading, setLoading]       = useState(false);
  const [savingId, setSavingId]     = useState(null);
  const [error, setError]           = useState("");
  const [message, setMessage]       = useState("");

  /* -------- load & merge -------- */
  const loadCategories = async () => {
    try {
      setLoading(true);
      setError("");
      setMessage("");

      // 1. Master Category list
      const masters = await listCollection("Category", {
        where: [["IsDelete", "==", 0]],
      });
      masters.sort((a, b) =>
        String(a.CategoryName || "").localeCompare(String(b.CategoryName || ""))
      );

      // 2. Existing loyalty rates
      const rates = await listCollection("LoyaltyCategories");

      // 3. Index by CategoryCode (primary) + CategoryName (fallback)
      const rateByCode = new Map();
      const rateByName = new Map();
      for (const r of rates) {
        if (r.CategoryCode) rateByCode.set(String(r.CategoryCode), r);
        if (r.CategoryName) rateByName.set(String(r.CategoryName).toLowerCase(), r);
      }

      // 4. Merge: master categories + their rates
      const merged = masters.map((m) => {
        const r =
          rateByCode.get(String(m.CategoryCode)) ||
          rateByName.get(String(m.CategoryName).toLowerCase()) ||
          null;

        return {
          CategoryCode:    m.CategoryCode || "",
          CategoryName:    m.CategoryName || "",
          LoyaltyDocId:    r?.id ?? null,      // Firestore doc id
          PointsPerAmount: r?.PointsPerAmount ?? 100,
          IsActive:        r ? Boolean(r.IsActive) : false,
        };
      });

      setCategories(merged);
    } catch (err) {
      console.error("LOAD CATEGORIES:", err);
      setError(err?.message || "Failed to load categories");
      setCategories([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadCategories(); }, []);

  /* -------- upsert helper -------- */
  const upsertRate = async (category, patch) => {
    if (category.LoyaltyDocId) {
      await updateDocById("LoyaltyCategories", category.LoyaltyDocId, patch, {
        username,
      });
      return category.LoyaltyDocId;
    }
    const id = await createDoc("LoyaltyCategories", {
      CategoryCode:    category.CategoryCode,
      CategoryName:    category.CategoryName,
      PointsPerAmount: Number(category.PointsPerAmount || 0),
      IsActive:        Boolean(category.IsActive),
      ...patch,
    }, { username });
    return id;
  };

  /* -------- local edits -------- */
  const handleRateChange = (categoryCode, value) => {
    if (!canEditLoyalty) return;
    setCategories((prev) =>
      prev.map((c) =>
        c.CategoryCode === categoryCode
          ? { ...c, PointsPerAmount: value }
          : c
      )
    );
  };

  /* -------- toggle -------- */
  const handleToggle = async (category) => {
    if (!canEditLoyalty) return;
    const newStatus = !category.IsActive;

    // Optimistic update
    setCategories((prev) =>
      prev.map((c) =>
        c.CategoryCode === category.CategoryCode
          ? { ...c, IsActive: newStatus }
          : c
      )
    );

    try {
      setSavingId(category.CategoryCode);
      setError(""); setMessage("");

      const id = await upsertRate(category, { IsActive: newStatus });

      // Record the new doc id so future saves can update in place
      setCategories((prev) =>
        prev.map((c) =>
          c.CategoryCode === category.CategoryCode
            ? { ...c, LoyaltyDocId: id, IsActive: newStatus }
            : c
        )
      );

      setMessage(
        `${category.CategoryName} ${newStatus ? "enabled" : "disabled"} successfully.`
      );
    } catch (err) {
      console.error("TOGGLE CATEGORY:", err);
      // Roll back
      setCategories((prev) =>
        prev.map((c) =>
          c.CategoryCode === category.CategoryCode
            ? { ...c, IsActive: category.IsActive }
            : c
        )
      );
      setError(err?.message || "Failed to update category");
    } finally {
      setSavingId(null);
    }
  };

  /* -------- save rate -------- */
  const saveRate = async (category) => {
    if (!canEditLoyalty) return;

    const rate = Number(category.PointsPerAmount);
    if (!rate || Number.isNaN(rate) || rate <= 0) {
      setError(`Please enter a valid points rate for ${category.CategoryName}.`);
      return;
    }

    try {
      setSavingId(category.CategoryCode);
      setError(""); setMessage("");

      const id = await upsertRate(category, {
        PointsPerAmount: rate,
        IsActive:        category.IsActive,
      });

      setCategories((prev) =>
        prev.map((c) =>
          c.CategoryCode === category.CategoryCode
            ? { ...c, LoyaltyDocId: id, PointsPerAmount: rate }
            : c
        )
      );

      setMessage(`${category.CategoryName} rate saved successfully.`);
    } catch (err) {
      console.error("SAVE CATEGORY RATE:", err);
      setError(err?.message || "Failed to save category rate");
    } finally {
      setSavingId(null);
    }
  };

  return (
    <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
      <div className="border-b px-6 py-6">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-2xl font-semibold">Category Rates</h2>
            <p className="mt-1 text-sm text-gray-500">
              Set loyalty points rates for each product category.
            </p>
          </div>
          <button
            type="button" onClick={loadCategories} disabled={loading}
            className="w-fit rounded-xl border border-gray-300 px-4 py-2.5 text-sm font-medium transition hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? "Loading…" : "↻ Refresh"}
          </button>
        </div>
      </div>

      {!canEditLoyalty && (
        <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
          Read-only mode — you cannot modify rates.
        </div>
      )}
      {message && (
        <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
          {message}
        </div>
      )}
      {error && (
        <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}

      <div className="overflow-x-auto p-6">
        <table className="w-full min-w-[800px] text-left text-sm">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-5 py-4 font-semibold">Category Code</th>
              <th className="px-5 py-4 font-semibold">Category Name</th>
              <th className="px-5 py-4 font-semibold">Points Rate</th>
              <th className="px-5 py-4 font-semibold">Status</th>
              <th className="px-5 py-4 text-right font-semibold">Action</th>
            </tr>
          </thead>
          <tbody>
            {categories.map((category) => {
              const isSaving = savingId === category.CategoryCode;
              return (
                <tr
                  key={category.CategoryCode || category.CategoryName}
                  className="border-t border-gray-100 transition hover:bg-[#fffaf0]"
                >
                  <td className="px-5 py-4">
                    <span className="rounded-lg bg-gray-100 px-3 py-1.5 text-xs font-semibold text-gray-700">
                      {category.CategoryCode || "-"}
                    </span>
                  </td>
                  <td className="px-5 py-4">
                    <div className="font-medium text-gray-900">{category.CategoryName}</div>
                  </td>
                  <td className="px-5 py-4">
                    <div className="flex items-center gap-2">
                      <span className="whitespace-nowrap text-gray-500">
                        1 point / Rs.
                      </span>
                      <input
                        type="number" min="1" step="0.01"
                        value={category.PointsPerAmount}
                        onChange={(e) => handleRateChange(category.CategoryCode, e.target.value)}
                        disabled={!canEditLoyalty || isSaving}
                        className="w-28 rounded-xl border border-gray-200 px-3 py-2.5 text-sm outline-none transition focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20 disabled:bg-gray-100"
                      />
                    </div>
                  </td>
                  <td className="px-5 py-4">
                    <div className="flex items-center gap-3">
                      <button
                        type="button"
                        onClick={() => handleToggle(category)}
                        disabled={isSaving || !canEditLoyalty}
                        className={`relative h-6 w-11 shrink-0 rounded-full transition ${
                          category.IsActive ? "bg-[#e99a00]" : "bg-gray-300"
                        } disabled:opacity-50 disabled:cursor-not-allowed`}
                      >
                        <span
                          className={`absolute top-1 h-4 w-4 rounded-full bg-white transition-all ${
                            category.IsActive ? "left-6" : "left-1"
                          }`}
                        />
                      </button>
                      <span
                        className={`text-xs font-semibold ${
                          category.IsActive ? "text-green-600" : "text-gray-500"
                        }`}
                      >
                        {category.IsActive ? "Enabled" : "Disabled"}
                      </span>
                    </div>
                  </td>
                  <td className="px-5 py-4 text-right">
                    {canEditLoyalty && (
                      <button
                        type="button"
                        onClick={() => saveRate(category)}
                        disabled={isSaving}
                        className="rounded-xl bg-[#e99a00] px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-[#d88d00] disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {isSaving ? "Saving…" : "Save"}
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {loading && (
          <div className="p-10 text-center text-sm text-gray-500">
            Loading product categories…
          </div>
        )}
        {!loading && categories.length === 0 && (
          <div className="p-10 text-center text-sm text-gray-500">
            No product categories found.
          </div>
        )}
      </div>
    </section>
  );
}

/* =====================================================
   CUSTOMERS
===================================================== */
function Customers({ canAdd = false, username }) {
  const [allCustomers, setAllCustomers] = useState([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState("");
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);
  const [saving, setSaving]   = useState(false);
  const [error, setError]     = useState("");
  const [message, setMessage] = useState("");

  const [form, setForm] = useState({
    customerName: "",
    phone:        "",
    customerType: "Retail",
    isEnrolled:   true,
  });

  /* -------- load all customers -------- */
  const loadAllCustomers = async () => {
    try {
      setLoading(true);
      setError("");

      const rows = await listCollection("LoyaltyCustomers");
      rows.sort((a, b) =>
        String(a.CustomerName || "").localeCompare(String(b.CustomerName || ""))
      );
      setAllCustomers(rows);

      if (rows.length > 0 && !selectedCustomerId) {
        setSelectedCustomerId(rows[0].id);
      }
    } catch (err) {
      console.error("LOAD CUSTOMERS:", err);
      setError(err?.message || "Failed to load customers");
      setAllCustomers([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadAllCustomers(); }, []);

  /* -------- filter client-side -------- */
  const customers = useMemo(() => {
    const s = search.trim().toLowerCase();
    if (!s) return allCustomers;
    return allCustomers.filter((c) => {
      const fields = [c.CustomerCode, c.CustomerName, c.Phone];
      return fields.join(" ").toLowerCase().includes(s);
    });
  }, [allCustomers, search]);

  /* -------- selected customer -------- */
  const selectedCustomer =
    allCustomers.find((c) => c.id === selectedCustomerId) || null;

  const updateForm = (name, value) =>
    setForm((prev) => ({ ...prev, [name]: value }));

  /* -------- next customer code -------- */
  const generateCustomerCode = () => {
    let max = 0;
    for (const c of allCustomers) {
      const m = String(c.CustomerCode || "").match(/(\d+)$/);
      if (m) {
        const n = parseInt(m[1], 10);
        if (n > max) max = n;
      }
    }
    return `CUS${String(max + 1).padStart(5, "0")}`;
  };

  /* -------- add customer -------- */
  const addCustomer = async () => {
    if (!canAdd) {
      setError("You do not have permission to add customers.");
      return;
    }
    if (!form.customerName.trim()) {
      setError("Customer name is required.");
      return;
    }

    try {
      setSaving(true);
      setError(""); setMessage("");

      // Duplicate check by phone (if a phone was provided)
      if (form.phone.trim()) {
        const dup = allCustomers.find(
          (c) => String(c.Phone || "").trim() === form.phone.trim()
        );
        if (dup) {
          setError(`A customer with phone ${form.phone.trim()} already exists.`);
          return;
        }
      }

      const code = generateCustomerCode();

      await createDoc("LoyaltyCustomers", {
        CustomerCode: code,
        CustomerName: form.customerName.trim(),
        Phone:        form.phone.trim() || null,
        CustomerType: form.customerType || "Retail",
        IsEnrolled:   Boolean(form.isEnrolled),
        LoyaltyPoints: 0,
        TotalEarned:   0,
        TotalRedeemed: 0,
      }, { customId: code, username });

      setForm({ customerName: "", phone: "", customerType: "Retail", isEnrolled: true });
      setMessage(`Customer ${code} added successfully.`);
      await loadAllCustomers();
    } catch (err) {
      console.error("ADD CUSTOMER:", err);
      setError(err?.message || "Failed to add customer");
    } finally {
      setSaving(false);
    }
  };

  return (
    <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
      <div className="border-b px-6 py-6">
        <h2 className="text-2xl font-semibold">Customers</h2>
        <p className="mt-1 text-sm text-gray-500">
          Manage customers enrolled in the loyalty program.
        </p>
      </div>

      {message && (
        <div className="mx-6 mt-5 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-700">
          {message}
        </div>
      )}
      {error && (
        <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}
      {!canAdd && (
        <div className="mx-6 mt-5 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs font-medium text-amber-700">
          Read-only mode — you cannot add new customers.
        </div>
      )}

      {/* Select customer */}
      <div className="border-b p-6">
        <div className="max-w-xl">
          <label className="mb-2 block text-sm font-semibold">Select Customer</label>
          <select
            value={selectedCustomerId}
            onChange={(e) => setSelectedCustomerId(e.target.value)}
            disabled={loading}
            className="w-full rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
          >
            <option value="">
              {loading
                ? "Loading customers…"
                : allCustomers.length === 0
                ? "No customers available"
                : "Select Customer"}
            </option>
            {allCustomers.map((c) => (
              <option key={c.id} value={c.id}>
                {c.CustomerCode} - {c.CustomerName}
              </option>
            ))}
          </select>
        </div>

        {selectedCustomer && (
          <div className="mt-4 grid gap-4 rounded-xl border bg-gray-50 p-5 sm:grid-cols-2 lg:grid-cols-4">
            <div>
              <p className="text-xs text-gray-500">Customer</p>
              <p className="mt-1 font-semibold">{selectedCustomer.CustomerName}</p>
              <p className="text-xs text-gray-500">{selectedCustomer.CustomerCode}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500">Phone</p>
              <p className="mt-1 font-semibold">{selectedCustomer.Phone || "-"}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500">Loyalty Points</p>
              <p className="mt-1 text-xl font-bold text-[#e99a00]">
                {selectedCustomer.LoyaltyPoints ?? 0}
              </p>
            </div>
            <div>
              <p className="text-xs text-gray-500">Status</p>
              <p className="mt-1 font-semibold">
                {selectedCustomer.IsEnrolled ? "Enrolled" : "Not Enrolled"}
              </p>
            </div>
          </div>
        )}
      </div>

      {/* Add customer row */}
      {canAdd && (
        <div className="grid gap-3 border-b bg-gray-50 p-6 md:grid-cols-5">
          <input
            placeholder="Customer name" value={form.customerName}
            onChange={(e) => updateForm("customerName", e.target.value)}
            className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
          />
          <input
            placeholder="Phone" value={form.phone}
            onChange={(e) => updateForm("phone", e.target.value)}
            className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
          />
          <select
            value={form.customerType}
            onChange={(e) => updateForm("customerType", e.target.value)}
            className="rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm outline-none focus:border-[#e99a00]"
          >
            <option value="Retail">Retail</option>
            <option value="Wholesale">Wholesale</option>
          </select>
          <button
            type="button" onClick={addCustomer} disabled={saving}
            className="rounded-xl bg-[#e99a00] px-5 py-3 text-sm font-semibold text-white transition hover:bg-[#d88d00] disabled:opacity-50"
          >
            {saving ? "Adding…" : "Add Customer"}
          </button>
        </div>
      )}

      {/* Search + table */}
      <div className="border-b p-6">
        <input
          value={search} onChange={(e) => setSearch(e.target.value)}
          placeholder="Search by code, name or phone…"
          className="w-full max-w-md rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-[#e99a00] focus:ring-2 focus:ring-[#e99a00]/20"
        />
      </div>

      <div className="overflow-x-auto">
        <table className="w-full min-w-[850px] text-left text-sm">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-4">Code</th>
              <th className="px-6 py-4">Customer</th>
              <th className="px-6 py-4">Type</th>
              <th className="px-6 py-4">Points</th>
              <th className="px-6 py-4">Earned</th>
              <th className="px-6 py-4">Redeemed</th>
              <th className="px-6 py-4">Status</th>
            </tr>
          </thead>
          <tbody>
            {customers.map((c) => (
              <tr
                key={c.id}
                onClick={() => setSelectedCustomerId(c.id)}
                className={`cursor-pointer border-t border-gray-100 transition hover:bg-[#fffaf0] ${
                  selectedCustomerId === c.id ? "bg-[#fff7e6]" : ""
                }`}
              >
                <td className="px-6 py-4 font-medium">{c.CustomerCode}</td>
                <td className="px-6 py-4">
                  <div className="font-medium">{c.CustomerName}</div>
                  <div className="text-xs text-gray-500">{c.Phone || "-"}</div>
                </td>
                <td className="px-6 py-4">{c.CustomerType}</td>
                <td className="px-6 py-4">
                  <span className="font-bold text-[#e99a00]">{c.LoyaltyPoints ?? 0}</span>
                </td>
                <td className="px-6 py-4">{c.TotalEarned ?? 0}</td>
                <td className="px-6 py-4">{c.TotalRedeemed ?? 0}</td>
                <td className="px-6 py-4">
                  <span
                    className={`rounded-full px-3 py-1 text-xs font-semibold ${
                      c.IsEnrolled
                        ? "bg-green-100 text-green-700"
                        : "bg-gray-100 text-gray-600"
                    }`}
                  >
                    {c.IsEnrolled ? "Enrolled" : "Not Enrolled"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {loading && (
          <div className="p-10 text-center text-sm text-gray-500">
            Loading customers…
          </div>
        )}
        {!loading && customers.length === 0 && (
          <div className="p-10 text-center text-sm text-gray-500">
            No customers found.
          </div>
        )}
      </div>
    </section>
  );
}

/* =====================================================
   TRANSACTIONS (read-only — last 500)
===================================================== */
function Transactions() {
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading]           = useState(false);
  const [error, setError]               = useState("");

  const loadTransactions = async () => {
    try {
      setLoading(true);
      setError("");

      // 1. Last 500 transactions
      const { getDocs } = await import("firebase/firestore");
      const snap = await getDocs(
        query(
          collection(db, "LoyaltyTransactions"),
          orderBy("CreatedAt", "desc"),
          limit(500)
        )
      );

      const txs = snap.docs
        .map((d) => ({ id: d.id, ...d.data() }))
        .filter((t) => t._meta !== true);

      // 2. Reference data for joins
      const [customers, categories] = await Promise.all([
        listCollection("LoyaltyCustomers"),
        listCollection("LoyaltyCategories"),
      ]);

      const custByDoc = new Map(customers.map((c) => [c.id, c]));
      const custByCode = new Map(
        customers.map((c) => [String(c.CustomerCode || ""), c])
      );
      const catByDoc = new Map(categories.map((c) => [c.id, c]));

      // 3. Merge
      setTransactions(
        txs.map((t) => {
          const customer =
            custByDoc.get(t.CustomerId) ||
            custByCode.get(String(t.CustomerCode || "")) ||
            null;
          const category = catByDoc.get(t.CategoryId) || null;

          return {
            id:             t.id,
            TransactionType: t.TransactionType,
            ReferenceNo:    t.ReferenceNo,
            Amount:         t.Amount,
            Points:         t.Points,
            PaymentMethod:  t.PaymentMethod,
            CreatedAt:      t.CreatedAt,
            CustomerName:   customer?.CustomerName || t.CustomerName || "-",
            CustomerCode:   customer?.CustomerCode || t.CustomerCode || "-",
            CategoryName:   category?.CategoryName || t.CategoryName || "-",
          };
        })
      );
    } catch (err) {
      console.error("LOAD TRANSACTIONS:", err);
      setError(err?.message || "Failed to load transactions");
      setTransactions([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadTransactions(); }, []);

  const formatDate = (v) => {
    if (!v) return "-";
    try {
      if (typeof v?.toDate === "function") return v.toDate().toLocaleString();
      return new Date(v).toLocaleString();
    } catch {
      return "-";
    }
  };

  return (
    <section className="rounded-xl border border-gray-300 bg-white shadow-sm">
      <div className="flex flex-col gap-4 border-b px-6 py-6 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h2 className="text-2xl font-semibold">Transactions</h2>
          <p className="mt-1 text-sm text-gray-500">
            Latest 500 loyalty entries (earned and redeemed).
          </p>
        </div>
        <button
          type="button" onClick={loadTransactions} disabled={loading}
          className="w-fit rounded-xl border border-gray-300 px-4 py-2 text-sm font-medium hover:bg-gray-50 disabled:opacity-50"
        >
          {loading ? "Loading…" : "↻ Refresh"}
        </button>
      </div>

      {error && (
        <div className="mx-6 mt-5 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full min-w-[1100px] text-left text-sm">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-4">Date</th>
              <th className="px-6 py-4">Customer</th>
              <th className="px-6 py-4">Type</th>
              <th className="px-6 py-4">Reference</th>
              <th className="px-6 py-4">Amount</th>
              <th className="px-6 py-4">Points</th>
              <th className="px-6 py-4">Payment</th>
              <th className="px-6 py-4">Category</th>
            </tr>
          </thead>
          <tbody>
            {transactions.map((t) => (
              <tr key={t.id} className="border-t border-gray-100">
                <td className="whitespace-nowrap px-6 py-4">{formatDate(t.CreatedAt)}</td>
                <td className="px-6 py-4">
                  <div className="font-medium">{t.CustomerName}</div>
                  <div className="text-xs text-gray-500">{t.CustomerCode}</div>
                </td>
                <td className="px-6 py-4">
                  <span
                    className={`rounded-full px-3 py-1 text-xs font-semibold ${
                      String(t.TransactionType).toUpperCase() === "EARN"
                        ? "bg-green-100 text-green-700"
                        : "bg-red-100 text-red-700"
                    }`}
                  >
                    {t.TransactionType}
                  </span>
                </td>
                <td className="px-6 py-4">{t.ReferenceNo || "-"}</td>
                <td className="px-6 py-4">Rs.{Number(t.Amount || 0).toFixed(2)}</td>
                <td className="px-6 py-4 font-semibold">{t.Points}</td>
                <td className="px-6 py-4">{t.PaymentMethod || "-"}</td>
                <td className="px-6 py-4">{t.CategoryName}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {loading && (
          <div className="p-10 text-center text-sm text-gray-500">
            Loading transactions…
          </div>
        )}
        {!loading && transactions.length === 0 && (
          <div className="p-10 text-center text-sm text-gray-500">
            No loyalty transactions found.
          </div>
        )}
      </div>
    </section>
  );
}